"use client";

import { useState } from "react";
import { useLocale } from "next-intl";
import { Minus, Plus, X, Check } from "lucide-react";
import { useCartStore } from "@/lib/store";
import {
  OperationsFrame,
  OperationsIntro,
} from "@/components/kage/operations/Operations";
import { useOperationsCopy } from "@/components/kage/operations/copy";
import {
  createLocalDraft,
  LOCAL_DRAFT_KEY,
  type DraftAddress,
  type LocalDraft,
} from "@/components/kage/operations/draft";
import styles from "@/components/kage/operations/operations.module.css";

const blankAddress: DraftAddress = {
  name: "",
  street: "",
  city: "",
  state: "",
  zipCode: "",
  country: "",
  type: "business",
};

export default function CheckoutPage() {
  const copy = useOperationsCopy();
  const locale = useLocale();
  const {
    items: cartItems,
    updateQuantity,
    removeItem,
    getTotalPrice,
  } = useCartStore();
  const [address, setAddress] = useState<DraftAddress>(blankAddress);
  const [paymentPreference, setPaymentPreference] =
    useState<LocalDraft["paymentPreference"]>("");
  const [reference, setReference] = useState("");
  const [notes, setNotes] = useState("");
  const [reviewed, setReviewed] = useState(false);
  const [saveState, setSaveState] = useState<"idle" | "saved" | "error">(
    "idle",
  );
  const total = getTotalPrice();
  const money = new Intl.NumberFormat(locale, {
    style: "currency",
    currency: "EUR",
  });
  const fields: Array<{
    key: Exclude<keyof DraftAddress, "type">;
    label: string;
    autoComplete: string;
  }> = [
    { key: "name", label: copy.name, autoComplete: "organization" },
    { key: "street", label: copy.street, autoComplete: "street-address" },
    { key: "city", label: copy.city, autoComplete: "address-level2" },
    { key: "state", label: copy.region, autoComplete: "address-level1" },
    { key: "zipCode", label: copy.postal, autoComplete: "postal-code" },
    { key: "country", label: copy.country, autoComplete: "country-name" },
  ];
  const saveDraft = () => {
    if (!reviewed) return;
    try {
      const draft = createLocalDraft(
        cartItems,
        address,
        paymentPreference,
        reference,
        notes,
        new Date().toISOString(),
      );
      window.localStorage.setItem(LOCAL_DRAFT_KEY, JSON.stringify(draft));
      setSaveState("saved");
    } catch {
      setSaveState("error");
    }
  };

  return (
    <OperationsFrame routeId="checkout" mode="ambient" className={styles.publicScope}>
      <OperationsIntro
        id="draft-intro"
        label={copy.draftLabel}
        title={copy.draftTitle}
        body={copy.draftBody}
      />
      <section
        id="draft-items"
        className={styles.section}
        aria-labelledby="draft-items-title"
        data-fx="form-feedback"
      >
        <h2 id="draft-items-title" className={styles.sectionTitle}>
          {copy.draftItems}
        </h2>
        {cartItems.length === 0 ? (
          <div className={styles.empty}>
            <h3>{copy.draftEmpty}</h3>
            <p>{copy.draftEmptyBody}</p>
            <div className={styles.actions}>
              <a className={styles.link} href={`/${locale}/productos`}>
                {copy.catalogue}
              </a>
              <a className={styles.link} href={`/${locale}/contacto`}>
                {copy.contact}
              </a>
            </div>
          </div>
        ) : (
          <ul className={styles.items}>
            {cartItems.map(({ product, quantity }) => (
              <li className={styles.item} key={product.id}>
                <img
                  src={product.image}
                  alt=""
                  width="80"
                  height="80"
                  loading="lazy"
                />
                <div>
                  <h3>{product.name}</h3>
                  <p>{product.units}</p>
                  <span>{money.format(product.price)}</span>
                </div>
                <div className={styles.quantity}>
                  <button
                    type="button"
                    aria-label={`${copy.reduceQuantity}: ${product.name}`}
                    onClick={() =>
                      updateQuantity(product.id, Math.max(1, quantity - 1))
                    }
                    disabled={quantity <= 1}
                  >
                    <Minus aria-hidden="true" size={16} />
                  </button>
                  <output aria-label={`${copy.quantity}: ${product.name}`}>
                    {quantity}
                  </output>
                  <button
                    type="button"
                    aria-label={`${copy.addQuantity}: ${product.name}`}
                    onClick={() => updateQuantity(product.id, quantity + 1)}
                  >
                    <Plus aria-hidden="true" size={16} />
                  </button>
                </div>
                <span>{money.format(product.price * quantity)}</span>
                <button
                  type="button"
                  className={styles.iconButton}
                  aria-label={`${copy.remove}: ${product.name}`}
                  onClick={() => removeItem(product.id)}
                >
                  <X aria-hidden="true" size={18} />
                </button>
              </li>
            ))}
          </ul>
        )}
        <div className={styles.total}>
          <div>
            <p>{copy.draftTotal}</p>
            <small>{copy.draftTotalHelp}</small>
          </div>
          <output>{money.format(total)}</output>
        </div>
      </section>
      <section
        id="draft-details"
        className={`${styles.section} kage-form`}
        aria-labelledby="draft-details-title"
        data-fx="form-feedback"
      >
        <h2 id="draft-details-title" className={styles.sectionTitle}>
          {copy.draftDetails}
        </h2>
        <fieldset>
          <legend>{copy.draftAddress}</legend>
          <div className={styles.fieldGrid}>
            {fields.map(({ key, label, autoComplete }) => (
              <div className={styles.field} key={key}>
                <label htmlFor={`draft-${key}`}>{label}</label>
                <input
                  id={`draft-${key}`}
                  autoComplete={autoComplete}
                  value={address[key]}
                  onChange={(event) => {
                    setAddress({ ...address, [key]: event.target.value });
                    setSaveState("idle");
                  }}
                />
              </div>
            ))}
            <div className={styles.field}>
              <label htmlFor="draft-address-type">{copy.addressType}</label>
              <select
                id="draft-address-type"
                value={address.type}
                onChange={(event) =>
                  setAddress({
                    ...address,
                    type: event.target.value as DraftAddress["type"],
                  })
                }
              >
                <option value="business">{copy.business}</option>
                <option value="home">{copy.personal}</option>
              </select>
            </div>
          </div>
        </fieldset>
        <div className={styles.fieldGrid}>
          <div className={styles.field}>
            <label htmlFor="draft-payment">{copy.draftPayment}</label>
            <select
              id="draft-payment"
              aria-describedby="draft-payment-help"
              value={paymentPreference}
              onChange={(event) =>
                setPaymentPreference(
                  event.target.value as LocalDraft["paymentPreference"],
                )
              }
            >
              <option value="">{copy.paymentNone}</option>
              <option value="card">{copy.paymentCard}</option>
              <option value="bank">{copy.paymentBank}</option>
              <option value="paypal">{copy.paymentPaypal}</option>
            </select>
            <small id="draft-payment-help">{copy.draftPaymentHelp}</small>
          </div>
          <div className={styles.field}>
            <label htmlFor="draft-reference">{copy.draftPromo}</label>
            <input
              id="draft-reference"
              value={reference}
              onChange={(event) => setReference(event.target.value)}
            />
          </div>
        </div>
        <div className={styles.field}>
          <label htmlFor="draft-notes">{copy.draftNotes}</label>
          <textarea
            id="draft-notes"
            value={notes}
            rows={4}
            onChange={(event) => setNotes(event.target.value)}
          />
        </div>
      </section>
      <section
        id="draft-result"
        className={styles.section}
        aria-label={copy.draftSave}
        data-fx="form-feedback"
      >
        <label className={styles.check}>
          <input
            type="checkbox"
            checked={reviewed}
            onChange={(event) => setReviewed(event.target.checked)}
          />
          {copy.draftReview}
        </label>
        <div className={styles.actions}>
          <button
            type="button"
            className={styles.button}
            disabled={!reviewed}
            onClick={saveDraft}
          >
            {copy.draftSave}
            <Check aria-hidden="true" size={18} />
          </button>
          <a className={styles.link} href={`/${locale}/contacto`}>
            {copy.contact}
          </a>
        </div>
        <div aria-live="polite">
          {saveState === "saved" && (
            <div className={styles.feedback} role="status">
              <h2>{copy.draftSaved}</h2>
              <p>{copy.draftSavedBody}</p>
            </div>
          )}
          {saveState === "error" && (
            <p className={styles.feedback} role="alert">
              {copy.draftSaveError}
            </p>
          )}
        </div>
      </section>
    </OperationsFrame>
  );
}

"use client";

/**
 * EJEMPLO DE INTEGRACI├ôN - LOGIN SEGURO
 *
 * Este es un ejemplo completo de c├│mo integrar el sistema de autenticaci├│n segura
 * en una p├ígina de login de Next.js con TypeScript.
 *
 * Caracter├¡sticas implementadas:
 * - Login con contrase├▒a legacy (NIF)
 * - Modal de advertencia autom├ítico para usuarios legacy
 * - Formulario de cambio de contrase├▒a con validaci├│n en tiempo real
 * - Modal de ├®xito tras cambiar contrase├▒a
 * - Gesti├│n de tokens JWT
 */

import { useState } from "react";
import { useLocale, useTranslations } from "next-intl";
import {
  OperationsFrame,
  OperationsIntro,
} from "@/components/kage/operations/Operations";
import { useOperationsCopy } from "@/components/kage/operations/copy";
import ops from "@/components/kage/operations/operations.module.css";
import { useRouter } from "next/navigation";
import LegacyPasswordWarningModal from "@/components/auth/LegacyPasswordWarningModal";
import PasswordChangeForm from "@/components/auth/PasswordChangeForm";
import PasswordChangeSuccessModal from "@/components/auth/PasswordChangeSuccessModal";

// Tipo de datos del cliente
interface Customer {
  id: number;
  code: string;
  fullName: string;
  email: string;
  isLegacyPassword: boolean;
}

// Resultado del cambio de contrase├▒a
interface PasswordChangeResult {
  crackTimeDisplay: string;
  strengthScore: number;
}

export default function LoginSecureExample() {
  const router = useRouter();
  const locale = useLocale();
  const t = useTranslations("customerArea");
  const copy = useOperationsCopy();

  // Estados del formulario de login
  const [customerCode, setCustomerCode] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState("");

  // Estados de modales
  const [showLegacyModal, setShowLegacyModal] = useState(false);
  const [showChangeForm, setShowChangeForm] = useState(false);
  const [showSuccessModal, setShowSuccessModal] = useState(false);

  // Datos del cliente y resultado
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [changeResult, setChangeResult] = useState<PasswordChangeResult | null>(
    null,
  );

  /**
   * Manejar el login
   */
  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    setIsLoading(true);

    try {
      // Llamar a la API de login seguro
      const response = await fetch(
        "http://localhost:5000/api/auth/secure/login",
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          credentials: "include", // Para enviar cookies
          body: JSON.stringify({
            customerCode,
            password,
          }),
        },
      );

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.message || "Error al iniciar sesi├│n");
      }

      if (data.success) {
        // Guardar token en localStorage (o sessionStorage)
        localStorage.setItem("accessToken", data.accessToken);

        // Guardar datos del cliente
        setCustomer(data.customer);

        // Si es contrase├▒a legacy, mostrar modal de advertencia
        if (data.showPasswordChangeModal) {
          setShowLegacyModal(true);
        } else {
          // Redirigir al dashboard
          router.push(`/${locale}/area-clientes`);
        }
      }
    } catch (error: any) {
      setError(error.message || "Error al iniciar sesi├│n");
    } finally {
      setIsLoading(false);
    }
  };

  /**
   * Usuario decide cambiar contrase├▒a ahora
   */
  const handleChangeNow = () => {
    setShowLegacyModal(false);
    setShowChangeForm(true);
  };

  /**
   * Usuario decide continuar sin cambiar (por ahora)
   */
  const handleContinue = () => {
    setShowLegacyModal(false);
    router.push(`/${locale}/area-clientes`);
  };

  /**
   * ├ëxito al cambiar contrase├▒a
   */
  const handlePasswordChangeSuccess = (data: any) => {
    setChangeResult({
      crackTimeDisplay: data.crackTimeDisplay,
      strengthScore: data.strengthScore,
    });
    setShowChangeForm(false);
    setShowSuccessModal(true);
  };

  /**
   * Cancelar cambio de contrase├▒a
   */
  const handleCancelChange = () => {
    setShowChangeForm(false);
    router.push(`/${locale}/area-clientes`);
  };

  /**
   * Cerrar modal de ├®xito y redirigir
   */
  const handleCloseSuccess = () => {
    setShowSuccessModal(false);
    router.push(`/${locale}/area-clientes`);
  };

  return (
    <OperationsFrame routeId="login-secure-example" mode="ambient">
      <OperationsIntro
        id="example-intro"
        label={copy.demoLabel}
        title={copy.accessTitle}
        body={copy.demoBody}
      />
      <section
        id="example-form"
        className={`${ops.section}  ${ops.formPanel}`}
        aria-label={copy.demoLabel}
        data-fx="form-feedback"
      >
        <form onSubmit={handleLogin} className="space-y-6">
          {/* C├│digo de cliente */}
          <div>
            <label
              htmlFor="customerCode"
              className="block text-sm font-medium text-foreground mb-2"
            >
              {t("login.clientCode")}
            </label>
            <input
              type="text"
              id="customerCode"
              value={customerCode}
              onChange={(e) => setCustomerCode(e.target.value)}
              className="w-full px-4 py-3 border border-border focus:ring-2 focus:ring-[var(--kage-accent)] focus:border-transparent"
              placeholder="0123456789"
              required
            />
          </div>

          {/* Contrase├▒a */}
          <div>
            <label
              htmlFor="password"
              className="block text-sm font-medium text-foreground mb-2"
            >
              {t("login.password")}
            </label>
            <div className="relative">
              <input
                type={showPassword ? "text" : "password"}
                id="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-4 py-3 border border-border focus:ring-2 focus:ring-[var(--kage-accent)] focus:border-transparent pr-12"
                placeholder={t("login.passwordPlaceholder")}
                required
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                aria-label={t("login.password")}
                aria-pressed={showPassword}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
              >
                {showPassword ? "­ƒæü´©Å" : "­ƒæü´©ÅÔÇì­ƒù¿´©Å"}
              </button>
            </div>
          </div>

          {/* Error */}
          {error && (
            <div className="bg-card border border-border p-4">
              <p className="text-sm text-foreground">{error}</p>
            </div>
          )}

          {/* Bot├│n de login */}
          <button
            type="submit"
            disabled={isLoading}
            className={`w-full py-3 px-6 font-normal text-foreground transition-all ${
              isLoading ? "bg-card cursor-not-allowed" : ""
            }`}
          >
            {isLoading ? t("login.loggingIn") : t("login.accessButton")}
          </button>
        </form>
      </section>
      <section id="example-help" className={ops.help} data-fx="form-feedback">
        <div className={ops.actions}>
          <a className={ops.link} href={`/${locale}`}>
            {copy.home}
          </a>
          <a className={ops.link} href={`/${locale}/area-clientes`}>
            {copy.accessLabel}
          </a>
        </div>
      </section>
      {/* Modal de advertencia legacy */}
      <LegacyPasswordWarningModal
        isOpen={showLegacyModal}
        onChangeNow={handleChangeNow}
        onContinue={handleContinue}
      />

      {/* Formulario de cambio de contrase├▒a */}
      {showChangeForm && customer && (
        <div className="fixed inset-0 bg-background/60 z-50 overflow-auto">
          <PasswordChangeForm
            customerId={customer.id}
            currentPassword={password}
            isLegacyPasswordChange={true}
            onSuccess={handlePasswordChangeSuccess}
            onCancel={handleCancelChange}
          />
        </div>
      )}

      {/* Modal de ├®xito */}
      {changeResult && (
        <PasswordChangeSuccessModal
          isOpen={showSuccessModal}
          crackTimeDisplay={changeResult.crackTimeDisplay}
          strengthScore={changeResult.strengthScore}
          onClose={handleCloseSuccess}
        />
      )}
    </OperationsFrame>
  );
}

'use client';

import React, { Component, ReactNode, ErrorInfo } from 'react';
import { AlertCircle, RefreshCw, Home, Bug } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { gmailCompose } from '@/components/editorial/facts';

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
  eventId: string | null;
}

/**
 * Error Boundary Global - Captura errores en toda la aplicaci├│n
 * Incluye logging autom├ítico y UI elegante de recuperaci├│n
 */
export class ErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = { hasError: false, error: null, errorInfo: null, eventId: null };
  }

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    // Generar ID ├║nico para tracking
    const eventId = `ERR-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
    
    this.setState({ errorInfo, eventId });

    // Log estructurado para debugging
    const errorLog = {
      eventId,
      message: error.message,
      stack: error.stack,
      componentStack: errorInfo.componentStack,
      timestamp: new Date().toISOString(),
      url: typeof window !== 'undefined' ? window.location.href : 'SSR',
      userAgent: typeof navigator !== 'undefined' ? navigator.userAgent : 'SSR',
    };

    console.error('­ƒÜ¿ [ErrorBoundary] Error capturado:', errorLog);

    // Enviar error al backend para logging centralizado
    this.reportErrorToBackend(errorLog);
  }

  private reportErrorToBackend = async (errorLog: Record<string, unknown>) => {
    try {
      await fetch('/api/logs/frontend-error', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(errorLog),
        credentials: 'include',
      }).catch(() => {
        // Silenciar errores de red
      });
    } catch {
      // No propagar errores del handler
    }
  };

  handleReset = () => {
    this.setState({ hasError: false, error: null, errorInfo: null, eventId: null });
    window.location.reload();
  };

  handleGoHome = () => {
    window.location.href = '/';
  };

  handleReportBug = () => {
    const subject = `Error en web - ${this.state.eventId}`;
    const body =
      `Hola,\n\nHe encontrado un error en la web:\n\n` +
      `ID: ${this.state.eventId}\n` +
      `Mensaje: ${this.state.error?.message}\n` +
      `URL: ${typeof window !== 'undefined' ? window.location.href : ''}\n\n` +
      `Descripci├│n de lo que estaba haciendo:\n\n`;
    window.open(
      gmailCompose('pedidos@granjamaripepa.com', subject, body),
      '_blank',
      'noopener,noreferrer'
    );
  };

  render() {
    if (this.state.hasError) {
      if (this.props.fallback) {
        return this.props.fallback;
      }

      return (
        <div className="min-h-screen bg-gradient-to-br from-slate-50 via-blue-50 to-indigo-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-xl p-8 max-w-md w-full">
            <div className="flex items-center justify-center w-16 h-16 bg-red-100 rounded-full mx-auto mb-4">
              <AlertCircle className="w-8 h-8 text-red-600" />
            </div>
            
            <h1 className="text-2xl font-bold text-gray-900 text-center mb-2">
              Algo sali├│ mal
            </h1>
            
            <p className="text-gray-600 text-center mb-4">
              Ha ocurrido un error inesperado. Nuestro equipo ha sido notificado.
            </p>

            {/* ID del error para soporte */}
            {this.state.eventId && (
              <div className="bg-blue-50 border border-blue-200 rounded-lg p-3 mb-4">
                <p className="text-xs text-blue-700 text-center">
                  C├│digo de error: <code className="font-mono font-bold">{this.state.eventId}</code>
                </p>
              </div>
            )}
            
            {/* Mensaje de error (en desarrollo) */}
            {process.env.NODE_ENV === 'development' && this.state.error && (
              <details className="bg-gray-50 rounded-lg p-4 mb-4">
                <summary className="text-xs text-gray-500 cursor-pointer">
                  Detalles t├®cnicos
                </summary>
                <pre className="text-xs text-red-600 font-mono mt-2 whitespace-pre-wrap overflow-auto max-h-40">
                  {this.state.error.message}
                  {'\n'}
                  {this.state.error.stack}
                </pre>
              </details>
            )}

            {/* Acciones */}
            <div className="space-y-3">
              <Button
                onClick={this.handleReset}
                className="w-full bg-blue-600 hover:bg-blue-700"
              >
                <RefreshCw className="w-4 h-4 mr-2" />
                Recargar p├ígina
              </Button>

              <div className="grid grid-cols-2 gap-3">
                <Button
                  onClick={this.handleGoHome}
                  variant="outline"
                  className="flex items-center justify-center gap-2"
                >
                  <Home className="w-4 h-4" />
                  Inicio
                </Button>

                <Button
                  onClick={this.handleReportBug}
                  variant="outline"
                  className="flex items-center justify-center gap-2"
                >
                  <Bug className="w-4 h-4" />
                  Reportar
                </Button>
              </div>
            </div>

            <p className="text-center text-gray-400 text-xs mt-6">
              ┬┐Necesitas ayuda? Llama al{' '}
              <a href="tel:968467514" className="text-blue-600 hover:underline">
                968 46 75 14
              </a>
            </p>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

