"use client";

import { useCallback, useEffect, useState } from "react";
import {
  AlertTriangle,
  CheckCircle2,
  Clock,
  KeyRound,
  LifeBuoy,
  MonitorSmartphone,
  RefreshCw,
  ShieldCheck,
  Wifi,
} from "lucide-react";
import {
  fetchSessions,
  revokeOtherSessionsRequest,
  revokeSessionRequest,
  type AdminSession,
} from "./admin-data";
import { gmailCompose } from "@/components/editorial/facts";
import styles from "./admin.module.css";

function deviceLabel(userAgent: string) {
  const value = userAgent.toLowerCase();
  if (/iphone|ipad|ios/.test(value)) return "iPhone / iPad";
  if (/android/.test(value)) return "Android";
  if (/windows/.test(value)) return "Windows";
  if (/mac os|macintosh/.test(value)) return "macOS";
  if (/linux/.test(value)) return "Linux";
  return "Navegador";
}

function formatDate(value: string) {
  if (!value) return "ÔÇö";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "ÔÇö";
  return new Intl.DateTimeFormat("es-ES", {
    day: "2-digit",
    month: "short",
    hour: "2-digit",
    minute: "2-digit",
  }).format(date);
}

export function AdminSecurity({
  onNotify,
}: {
  onNotify: (message: string) => void;
}) {
  const [sessions, setSessions] = useState<AdminSession[]>([]);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [confirming, setConfirming] = useState(false);
  const [error, setError] = useState("");

  const load = useCallback(async () => {
    setLoading(true);
    setError("");
    try {
      setSessions(await fetchSessions());
    } catch (failure) {
      setError(
        failure instanceof Error
          ? failure.message
          : "No se pudieron leer las sesiones.",
      );
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  useEffect(() => {
    if (!confirming) return;
    const timer = window.setTimeout(() => setConfirming(false), 4000);
    return () => window.clearTimeout(timer);
  }, [confirming]);

  const revoke = async (session: AdminSession) => {
    if (session.current) return;
    setBusy(true);
    try {
      await revokeSessionRequest(session);
      await load();
      onNotify("Sesi├│n revocada");
    } catch (failure) {
      onNotify(
        failure instanceof Error ? failure.message : "No se pudo revocar la sesi├│n",
      );
    } finally {
      setBusy(false);
    }
  };

  const revokeOthers = async () => {
    if (!confirming) {
      setConfirming(true);
      return;
    }
    setConfirming(false);
    setBusy(true);
    try {
      await revokeOtherSessionsRequest();
      await load();
      onNotify("Se han cerrado las dem├ís sesiones");
    } catch (failure) {
      onNotify(
        failure instanceof Error
          ? failure.message
          : "No se pudieron cerrar las otras sesiones",
      );
    } finally {
      setBusy(false);
    }
  };

  const current = sessions.find((session) => session.current);
  const activeCount = sessions.length;

  return (
    <div className={styles.security}>
      <header className={styles.pageHead}>
        <div>
          <span className={styles.kicker}>Seguridad</span>
          <h1 className={styles.pageTitle}>Sesiones y acceso.</h1>
          <p className={styles.pageDesc}>
            Controla desde d├│nde se ha entrado al panel, cu├ínto dura el acceso y
            qu├® hacer si algo falla. Las sesiones caducan solas a las 8 horas.
          </p>
        </div>
      </header>

      <div className={styles.securityStats}>
        <article>
          <MonitorSmartphone size={16} aria-hidden="true" />
          <b>{loading ? "ÔÇö" : activeCount}</b>
          <span>sesiones activas</span>
        </article>
        <article>
          <Clock size={16} aria-hidden="true" />
          <b>8 h</b>
          <span>duraci├│n m├íxima</span>
        </article>
        <article>
          <ShieldCheck size={16} aria-hidden="true" />
          <b>httpOnly</b>
          <span>cookie SameSite=Strict</span>
        </article>
        <article>
          <KeyRound size={16} aria-hidden="true" />
          <b>SHA-256</b>
          <span>token guardado con hash</span>
        </article>
      </div>

      <section className={styles.securityPanel}>
        <div className={styles.panelHead}>
          <div>
            <span className={styles.panelKicker}>Accesos</span>
            <h2>Sesiones abiertas</h2>
          </div>
          <div className={styles.securityActions}>
            <button
              type="button"
              className={styles.secondaryBtn}
              onClick={() => void load()}
              disabled={loading || busy}
            >
              <RefreshCw size={14} aria-hidden="true" /> Actualizar
            </button>
            <button
              type="button"
              className={styles.secondaryBtn}
              onClick={() => void revokeOthers()}
              disabled={busy || activeCount <= 1}
            >
              {confirming ? "Confirmar cierre" : "Cerrar las dem├ís"}
            </button>
          </div>
        </div>

        {error ? (
          <div className={styles.securityError} role="alert">
            <AlertTriangle size={15} aria-hidden="true" /> {error}
          </div>
        ) : null}

        {loading ? (
          <p className={styles.securityEmpty}>Leyendo sesionesÔÇª</p>
        ) : sessions.length === 0 ? (
          <p className={styles.securityEmpty}>No hay sesiones activas.</p>
        ) : (
          <ul className={styles.sessionList}>
            {sessions.map((session) => (
              <li key={session.token} className={session.current ? styles.sessionCurrent : undefined}>
                <span className={styles.sessionIcon}>
                  <MonitorSmartphone size={16} aria-hidden="true" />
                </span>
                <span className={styles.sessionMain}>
                  <b>
                    {deviceLabel(session.userAgent)}
                    {session.current ? <em>Esta sesi├│n</em> : null}
                  </b>
                  <small>
                    {session.name} ┬À {session.email}
                  </small>
                </span>
                <span className={styles.sessionMeta}>
                  <span>{session.ip || "IP interna"}</span>
                  <span>
                    Entr├│ {formatDate(session.createdAt)} ┬À caduca{" "}
                    {formatDate(session.expiresAt)}
                  </span>
                </span>
                <button
                  type="button"
                  className={styles.sessionRevoke}
                  onClick={() => void revoke(session)}
                  disabled={session.current || busy}
                >
                  {session.current ? "Actual" : "Revocar"}
                </button>
              </li>
            ))}
          </ul>
        )}

        {current ? (
          <p className={styles.securityHint}>
            <CheckCircle2 size={13} aria-hidden="true" /> Tu sesi├│n actual est├í
            protegida. Si cambias la contrase├▒a, se mantiene esta sesi├│n y se
            revocan las dem├ís.
          </p>
        ) : null}
      </section>

      <section className={styles.supportCard}>
        <div className={styles.supportIcon}>
          <LifeBuoy size={20} aria-hidden="true" />
        </div>
        <div>
          <span className={styles.panelKicker}>Si algo falla</span>
          <h2>Qu├® hacer antes de llamar.</h2>
          <ol className={styles.supportSteps}>
            <li>Comprueba que la VPN corporativa sigue conectada.</li>
            <li>Recarga el panel y vuelve a iniciar sesi├│n.</li>
            <li>
              Si el error es de red, no insistas: el acceso solo funciona desde
              la red interna o la VPN.
            </li>
            <li>
              Si el error contin├║a, escribe a{" "}
              <a
                href={gmailCompose(
                  "javier@mari-pepa.com",
                  "Incidencia en el panel de administraci├│n",
                )}
                target="_blank"
                rel="noopener noreferrer"
              >
                javier@mari-pepa.com
              </a>{" "}
              con la hora, la pantalla y el mensaje exacto.
            </li>
          </ol>
          <div className={styles.errorCodes}>
            <span><b>NETWORK_NOT_ALLOWED</b> ┬À VPN o red interna</span>
            <span><b>SESSION_REQUIRED</b> ┬À vuelve a entrar</span>
            <span><b>LOGIN_LOCKED</b> ┬À espera 15 minutos</span>
          </div>
        </div>
        <Wifi size={18} aria-hidden="true" className={styles.supportWifi} />
      </section>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import LegacyPasswordWarningModal from './LegacyPasswordWarningModal';
import FinalSecurityWarningModal from './FinalSecurityWarningModal';
import PasswordChangeForm from './PasswordChangeForm';
import PasswordChangeSuccessModal from './PasswordChangeSuccessModal';
import { secureFetch } from '@/lib/secureFetch';

interface AuthFlowManagerProps {
  showLegacyWarning: boolean;
  customerId: number;
  currentPassword: string;
  onFlowComplete: () => void;
}

/**
 * Gestor del flujo completo de cambio de contrase├▒a
 *
 * Maneja la secuencia:
 * 1. LegacyPasswordWarningModal (si showLegacyWarning = true)
 * 2. FinalSecurityWarningModal (si usuario hace clic en "Continuar de momento")
 * 3. PasswordChangeForm (si usuario acepta cambiar)
 * 4. PasswordChangeSuccessModal (tras cambio exitoso)
 */
export default function AuthFlowManager({
  showLegacyWarning,
  customerId,
  currentPassword,
  onFlowComplete
}: AuthFlowManagerProps) {
  const [showWarning, setShowWarning] = useState(showLegacyWarning);
  const [showFinalWarning, setShowFinalWarning] = useState(false);
  const [showChangeForm, setShowChangeForm] = useState(false);
  const [showSuccessModal, setShowSuccessModal] = useState(false);
  const [successData, setSuccessData] = useState<any>(null);

  const handleChangeNow = () => {
    setShowWarning(false);
    setShowFinalWarning(false);
    setShowChangeForm(true);
  };

  const handleContinue = () => {
    setShowWarning(false);
    setShowFinalWarning(true);
  };

  const handleAcceptRisk = async () => {
    setShowFinalWarning(false);

    // Increment dismissal counter in backend (using secureFetch for CSRF token)
    try {
      console.log('­ƒöä Calling dismiss-password-warning...');

      const response = await secureFetch('/api/auth/dismiss-password-warning', {
        method: 'POST'
      });

      console.log('­ƒôñ Dismiss response:', response);

      if (response.ok) {
        console.log('Ô£à Password warning dismissed successfully', response.data);
      } else {
        console.error('ÔØî Dismiss failed with status:', response.status);
      }
    } catch (error) {
      console.error('ÔØî Error dismissing password warning:', error);
      // Continue anyway - non-critical error
    }

    console.log('­ƒÅü Calling onFlowComplete...');
    onFlowComplete();
  };

  const handleChangeSuccess = (data: any) => {
    setShowChangeForm(false);
    setSuccessData(data);
    setShowSuccessModal(true);
  };

  const handleChangeCancel = () => {
    setShowChangeForm(false);
    onFlowComplete();
  };

  const handleSuccessClose = () => {
    setShowSuccessModal(false);
    onFlowComplete();
  };

  return (
    <>
      {/* Modal de advertencia inicial de contrase├▒a legacy */}
      <LegacyPasswordWarningModal
        isOpen={showWarning}
        onChangeNow={handleChangeNow}
        onContinue={handleContinue}
      />

      {/* Modal de advertencia final (├║ltima oportunidad) */}
      <FinalSecurityWarningModal
        isOpen={showFinalWarning}
        onChangeNow={handleChangeNow}
        onAcceptRisk={handleAcceptRisk}
      />

      {/* Formulario de cambio de contrase├▒a */}
      {showChangeForm && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl shadow-2xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
            <PasswordChangeForm
              customerId={customerId}
              currentPassword={currentPassword}
              isLegacyPasswordChange={true}
              onSuccess={handleChangeSuccess}
              onCancel={handleChangeCancel}
            />
          </div>
        </div>
      )}

      {/* Modal de ├®xito */}
      {successData && (
        <PasswordChangeSuccessModal
          isOpen={showSuccessModal}
          crackTimeDisplay={successData.crackTimeDisplay}
          strengthScore={successData.strengthScore}
          onClose={handleSuccessClose}
        />
      )}
    </>
  );
}

