'use client';

import React, { useState, useEffect } from 'react';
import { Shield, Eye, EyeOff, CheckCircle, XCircle, AlertCircle, Lock, Zap, Clock, AlertTriangle } from 'lucide-react';
import zxcvbn from 'zxcvbn';

interface PasswordChangeFormProps {
    customerId: number;
    currentPassword?: string; // Opcional si viene del modal legacy
    isLegacyPasswordChange?: boolean;
    onSuccess: (data: any) => void;
    onCancel: () => void;
}

interface PasswordStrength {
    score: number;
    crackTimeDisplay: string;
    feedback: {
        warning: string;
        suggestions: string[];
    };
    isPwned?: boolean;
}

/**
 * Formulario de cambio de contrase├▒a con validaci├│n en tiempo real
 *
 * Caracter├¡sticas:
 * - Barra de fortaleza visual con zxcvbn
 * - Estimaci├│n de tiempo de crackeo en tiempo real
 * - Check contra HaveIBeenPwned
 * - Feedback educativo
 * - Confirmaci├│n doble antes de enviar
 */
export default function PasswordChangeForm({
    customerId,
    currentPassword: initialCurrentPassword,
    isLegacyPasswordChange = false,
    onSuccess,
    onCancel
}: PasswordChangeFormProps) {
    const [currentPassword, setCurrentPassword] = useState(initialCurrentPassword || '');
    const [newPassword, setNewPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [showCurrentPassword, setShowCurrentPassword] = useState(false);
    const [showNewPassword, setShowNewPassword] = useState(false);
    const [showConfirmPassword, setShowConfirmPassword] = useState(false);
    const [isChecking, setIsChecking] = useState(false);
    const [showConfirmModal, setShowConfirmModal] = useState(false);
    const [error, setError] = useState('');
    const [strength, setStrength] = useState<PasswordStrength | null>(null);

    // Validar contrase├▒a en tiempo real con zxcvbn
    useEffect(() => {
        if (newPassword.length === 0) {
            setStrength(null);
            return;
        }

        const result = zxcvbn(newPassword, [
            'granjamaripepa',
            'granja',
            'maripepa'
        ]);

        setStrength({
            score: result.score,
            crackTimeDisplay: String(result.crack_times_display.offline_slow_hashing_1e4_per_second),
            feedback: {
                warning: result.feedback.warning || '',
                suggestions: result.feedback.suggestions || []
            }
        });

        // Verificar contra HaveIBeenPwned si la fortaleza es buena
        if (result.score >= 3 && newPassword.length >= 12) {
            checkPasswordPwned(newPassword);
        }
    }, [newPassword]);

    const checkPasswordPwned = async (password: string) => {
        try {
            const response = await fetch('/api/auth/check-password-pwned', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ password })
            });

            const data = await response.json();
            if (data.success && strength) {
                setStrength({
                    ...strength,
                    isPwned: data.isPwned
                });
            }
        } catch (error) {
            console.error('Error checking pwned password:', error);
        }
    };

    const getStrengthLabel = (score: number) => {
        const labels = ['Muy d├®bil', 'D├®bil', 'Regular', 'Fuerte', 'Muy fuerte'];
        return labels[score];
    };

    const getStrengthColor = (score: number) => {
        const colors = [
            'bg-red-500',
            'bg-orange-500',
            'bg-yellow-500',
            'bg-lime-500',
            'bg-green-600'
        ];
        return colors[score];
    };

    const getStrengthTextColor = (score: number) => {
        const colors = [
            'text-red-700',
            'text-orange-700',
            'text-yellow-700',
            'text-lime-700',
            'text-green-700'
        ];
        return colors[score];
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setError('');

        // Validaciones
        if (!currentPassword) {
            setError('Por favor, ingresa tu contrase├▒a actual');
            return;
        }

        if (newPassword.length < 12) {
            setError('La contrase├▒a debe tener al menos 12 caracteres');
            return;
        }

        if (newPassword !== confirmPassword) {
            setError('Las contrase├▒as no coinciden');
            return;
        }

        if (!strength || strength.score < 4) {
            setError('La contrase├▒a no es lo suficientemente fuerte (m├¡nimo: Muy fuerte)');
            return;
        }

        if (strength.isPwned) {
            setError('Esta contrase├▒a ha sido comprometida. Por favor, elige otra');
            return;
        }

        // Mostrar modal de confirmaci├│n
        setShowConfirmModal(true);
    };

    const handleConfirmedSubmit = async () => {
        setIsChecking(true);
        setError('');

        try {
            const response = await fetch('/api/auth/change-password', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                credentials: 'include', // ­ƒöÉ Enviar cookies con token JWT
                body: JSON.stringify({
                    currentPassword,
                    newPassword
                })
            });

            const data = await response.json();

            if (data.success) {
                onSuccess(data);
            } else {
                setError(data.message || 'Error al cambiar contrase├▒a');
                setShowConfirmModal(false);
            }
        } catch (error) {
            setError('Error de conexi├│n. Por favor, intenta de nuevo');
            setShowConfirmModal(false);
        } finally {
            setIsChecking(false);
        }
    };

    const isFormValid = currentPassword &&
        newPassword &&
        confirmPassword &&
        newPassword === confirmPassword &&
        strength &&
        strength.score >= 4 &&
        !strength.isPwned;

    return (
        <div className="max-w-2xl mx-auto p-6">
            <div className="bg-white rounded-2xl shadow-xl p-8">
                {/* Header */}
                <div className="mb-8">
                    <div className="flex items-center gap-3 mb-3">
                        <div className="bg-blue-100 p-3 rounded-full">
                            <Lock className="w-6 h-6 text-blue-600" />
                        </div>
                        <h2 className="text-2xl font-bold text-gray-800">
                            {isLegacyPasswordChange ? 'Protege tu cuenta' : 'Cambiar contrase├▒a'}
                        </h2>
                    </div>
                    <p className="text-gray-600 ml-[60px]">
                        Crea una contrase├▒a fuerte y ├║nica. Te guiaremos paso a paso.
                    </p>
                </div>

                <form onSubmit={handleSubmit} className="space-y-6">
                    {/* Contrase├▒a actual */}
                    {!initialCurrentPassword && (
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">
                                Contrase├▒a actual
                            </label>
                            <div className="relative">
                                <input
                                    type={showCurrentPassword ? 'text' : 'password'}
                                    value={currentPassword}
                                    onChange={(e) => setCurrentPassword(e.target.value)}
                                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent pr-12"
                                    placeholder="Tu contrase├▒a actual"
                                    required
                                />
                                <button
                                    type="button"
                                    onClick={() => setShowCurrentPassword(!showCurrentPassword)}
                                    className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-500 hover:text-gray-700"
                                >
                                    {showCurrentPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                                </button>
                            </div>
                        </div>
                    )}

                    {/* Nueva contrase├▒a */}
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                            Nueva contrase├▒a
                        </label>
                        <div className="relative">
                            <input
                                type={showNewPassword ? 'text' : 'password'}
                                value={newPassword}
                                onChange={(e) => setNewPassword(e.target.value)}
                                className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent pr-12"
                                placeholder="M├¡nimo 12 caracteres"
                                required
                            />
                            <button
                                type="button"
                                onClick={() => setShowNewPassword(!showNewPassword)}
                                className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-500 hover:text-gray-700"
                            >
                                {showNewPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                            </button>
                        </div>

                        {/* Barra de fortaleza */}
                        {strength && (
                            <div className="mt-4 space-y-3">
                                {/* Barra visual */}
                                <div className="space-y-2">
                                    <div className="flex justify-between items-center">
                                        <span className={`text-sm font-semibold ${getStrengthTextColor(strength.score)}`}>
                                            Fortaleza: {getStrengthLabel(strength.score)}
                                        </span>
                                        <span className="text-xs text-gray-500">
                                            {strength.score}/4
                                        </span>
                                    </div>
                                    <div className="w-full bg-gray-200 rounded-full h-2.5">
                                        <div
                                            className={`h-2.5 rounded-full transition-all duration-300 ${getStrengthColor(strength.score)}`}
                                            style={{ width: `${((strength.score + 1) / 5) * 100}%` }}
                                        ></div>
                                    </div>
                                </div>

                                {/* Tiempo de crackeo */}
                                <div className={`flex items-center gap-2 p-3 rounded-lg ${
                                    strength.score >= 4 ? 'bg-green-50 border border-green-200' :
                                    strength.score >= 3 ? 'bg-yellow-50 border border-yellow-200' :
                                    'bg-red-50 border border-red-200'
                                }`}>
                                    <Clock className={`w-5 h-5 flex-shrink-0 ${
                                        strength.score >= 4 ? 'text-green-600' :
                                        strength.score >= 3 ? 'text-yellow-600' :
                                        'text-red-600'
                                    }`} />
                                    <div className="flex-1">
                                        <p className="text-sm font-medium text-gray-800">
                                            Tiempo para crackear: <span className="font-bold">{strength.crackTimeDisplay}</span>
                                        </p>
                                        {strength.score >= 4 && (
                                            <p className="text-xs text-green-700 mt-0.5">
                                                ┬íExcelente! Esta contrase├▒a tardar├¡a siglos en ser crackeada.
                                            </p>
                                        )}
                                    </div>
                                    {strength.score >= 4 && (
                                        <CheckCircle className="w-5 h-5 text-green-600 flex-shrink-0" />
                                    )}
                                </div>

                                {/* Check HaveIBeenPwned */}
                                {strength.isPwned !== undefined && (
                                    <div className={`flex items-center gap-2 p-3 rounded-lg ${
                                        strength.isPwned ? 'bg-red-50 border border-red-200' : 'bg-green-50 border border-green-200'
                                    }`}>
                                        {strength.isPwned ? (
                                            <>
                                                <XCircle className="w-5 h-5 text-red-600 flex-shrink-0" />
                                                <p className="text-sm text-red-700">
                                                    <strong>Contrase├▒a comprometida:</strong> Esta contrase├▒a ha sido filtrada en brechas de seguridad. Elige otra.
                                                </p>
                                            </>
                                        ) : (
                                            <>
                                                <CheckCircle className="w-5 h-5 text-green-600 flex-shrink-0" />
                                                <p className="text-sm text-green-700">
                                                    Contrase├▒a segura: No est├í en bases de datos de contrase├▒as filtradas
                                                </p>
                                            </>
                                        )}
                                    </div>
                                )}

                                {/* Feedback de zxcvbn */}
                                {(strength.feedback.warning || strength.feedback.suggestions.length > 0) && (
                                    <div className="bg-blue-50 border border-blue-200 rounded-lg p-3 space-y-2">
                                        {strength.feedback.warning && (
                                            <p className="text-sm text-blue-800 flex items-start gap-2">
                                                <AlertCircle className="w-4 h-4 mt-0.5 flex-shrink-0" />
                                                {strength.feedback.warning}
                                            </p>
                                        )}
                                        {strength.feedback.suggestions.length > 0 && (
                                            <ul className="text-xs text-blue-700 space-y-1 ml-6 list-disc">
                                                {strength.feedback.suggestions.map((suggestion, idx) => (
                                                    <li key={idx}>{suggestion}</li>
                                                ))}
                                            </ul>
                                        )}
                                    </div>
                                )}
                            </div>
                        )}
                    </div>

                    {/* Confirmar contrase├▒a */}
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                            Confirmar nueva contrase├▒a
                        </label>
                        <div className="relative">
                            <input
                                type={showConfirmPassword ? 'text' : 'password'}
                                value={confirmPassword}
                                onChange={(e) => setConfirmPassword(e.target.value)}
                                className={`w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent pr-12 ${
                                    confirmPassword && newPassword !== confirmPassword
                                        ? 'border-red-300 bg-red-50'
                                        : 'border-gray-300'
                                }`}
                                placeholder="Repite tu nueva contrase├▒a"
                                required
                            />
                            <button
                                type="button"
                                onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                                className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-500 hover:text-gray-700"
                            >
                                {showConfirmPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                            </button>
                        </div>
                        {confirmPassword && newPassword !== confirmPassword && (
                            <p className="mt-2 text-sm text-red-600 flex items-center gap-1">
                                <XCircle className="w-4 h-4" />
                                Las contrase├▒as no coinciden
                            </p>
                        )}
                        {confirmPassword && newPassword === confirmPassword && (
                            <p className="mt-2 text-sm text-green-600 flex items-center gap-1">
                                <CheckCircle className="w-4 h-4" />
                                Las contrase├▒as coinciden
                            </p>
                        )}
                    </div>

                    {/* Error general */}
                    {error && (
                        <div className="bg-red-50 border border-red-200 rounded-lg p-4 flex items-start gap-2">
                            <AlertTriangle className="w-5 h-5 text-red-600 flex-shrink-0 mt-0.5" />
                            <p className="text-sm text-red-700">{error}</p>
                        </div>
                    )}

                    {/* Botones */}
                    <div className="flex gap-3 pt-4">
                        <button
                            type="button"
                            onClick={onCancel}
                            className="flex-1 px-6 py-3 border border-gray-300 rounded-lg text-gray-700 font-medium hover:bg-gray-50 transition-colors"
                        >
                            Cancelar
                        </button>
                        <button
                            type="submit"
                            disabled={!isFormValid || isChecking}
                            className={`flex-1 px-6 py-3 rounded-lg font-semibold transition-all ${
                                isFormValid && !isChecking
                                    ? 'bg-gradient-to-r from-green-600 to-green-700 hover:from-green-700 hover:to-green-800 text-white shadow-lg hover:shadow-xl'
                                    : 'bg-gray-300 text-gray-500 cursor-not-allowed'
                            }`}
                        >
                            {isChecking ? 'Cambiando...' : 'Cambiar contrase├▒a'}
                        </button>
                    </div>
                </form>
            </div>

            {/* Modal de confirmaci├│n */}
            {showConfirmModal && (
                <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full p-6">
                        <div className="flex items-center gap-3 mb-4">
                            <div className="bg-amber-100 p-3 rounded-full">
                                <AlertTriangle className="w-6 h-6 text-amber-600" />
                            </div>
                            <h3 className="text-xl font-bold text-gray-800">
                                Confirmar cambio de contrase├▒a
                            </h3>
                        </div>

                        <p className="text-gray-700 mb-6">
                            Vas a cambiar tu contrase├▒a. Esta acci├│n:
                        </p>

                        <ul className="space-y-2 mb-6 text-sm text-gray-700">
                            <li className="flex items-start gap-2">
                                <div className="w-1.5 h-1.5 rounded-full bg-blue-600 mt-2 flex-shrink-0"></div>
                                Cerrar├í todas tus sesiones en otros dispositivos
                            </li>
                            <li className="flex items-start gap-2">
                                <div className="w-1.5 h-1.5 rounded-full bg-blue-600 mt-2 flex-shrink-0"></div>
                                Invalidar├í todos los tokens de acceso anteriores
                            </li>
                            <li className="flex items-start gap-2">
                                <div className="w-1.5 h-1.5 rounded-full bg-green-600 mt-2 flex-shrink-0"></div>
                                Proteger├í tu cuenta con una contrase├▒a muy fuerte
                            </li>
                        </ul>

                        <p className="text-gray-800 font-medium mb-6">
                            ┬┐Confirmas que deseas cambiar tu contrase├▒a?
                        </p>

                        <div className="flex gap-3">
                            <button
                                onClick={() => setShowConfirmModal(false)}
                                disabled={isChecking}
                                className="flex-1 px-4 py-3 border border-gray-300 rounded-lg text-gray-700 font-medium hover:bg-gray-50 transition-colors disabled:opacity-50"
                            >
                                Cancelar
                            </button>
                            <button
                                onClick={handleConfirmedSubmit}
                                disabled={isChecking}
                                className="flex-1 px-4 py-3 bg-gradient-to-r from-green-600 to-green-700 hover:from-green-700 hover:to-green-800 text-white font-semibold rounded-lg transition-all shadow-lg hover:shadow-xl disabled:opacity-50"
                            >
                                {isChecking ? 'Cambiando...' : 'S├¡, cambiar ahora'}
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Lock, Eye, EyeOff, Check, X, AlertCircle, Loader2, Shield } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import toast from 'react-hot-toast';

interface ChangePasswordModalProps {
  isOpen: boolean;
  codigoCliente: string;
  currentPassword: string;
  onSuccess: () => void;
  onLogout?: () => void;
}

// Criterios de validaci├│n
const passwordCriteria = [
  { id: 'length', label: 'M├¡nimo 8 caracteres', test: (pwd: string) => pwd.length >= 8 },
  { id: 'uppercase', label: 'Una letra may├║scula', test: (pwd: string) => /[A-Z]/.test(pwd) },
  { id: 'lowercase', label: 'Una letra min├║scula', test: (pwd: string) => /[a-z]/.test(pwd) },
  { id: 'number', label: 'Un n├║mero', test: (pwd: string) => /[0-9]/.test(pwd) },
  { id: 'special', label: 'Un car├ícter especial (!@#$%...)', test: (pwd: string) => /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(pwd) },
];

export function ChangePasswordModal({
  isOpen,
  codigoCliente,
  currentPassword,
  onSuccess,
  onLogout
}: ChangePasswordModalProps) {
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showNewPassword, setShowNewPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [errors, setErrors] = useState<{ newPassword?: string; confirmPassword?: string; general?: string }>({});

  // Validaci├│n en tiempo real
  const getPasswordStrength = () => {
    return passwordCriteria.filter(c => c.test(newPassword)).length;
  };

  const validatePasswords = (): boolean => {
    const newErrors: { newPassword?: string; confirmPassword?: string } = {};

    // Validar nueva contrase├▒a
    const failedCriteria = passwordCriteria.filter(c => !c.test(newPassword));
    if (failedCriteria.length > 0) {
      newErrors.newPassword = `La contrase├▒a debe cumplir todos los requisitos`;
    }

    // Verificar que no sea igual a la actual (NIF)
    if (newPassword === currentPassword) {
      newErrors.newPassword = 'La nueva contrase├▒a no puede ser igual a tu NIF actual';
    }

    // Validar confirmaci├│n
    if (newPassword !== confirmPassword) {
      newErrors.confirmPassword = 'Las contrase├▒as no coinciden';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validatePasswords()) return;

    setIsLoading(true);
    setErrors({});

    try {
      const response = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/api/password/change`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        credentials: 'include',
        body: JSON.stringify({
          currentPassword: currentPassword,
          newPassword: newPassword
        })
      });

      const data = await response.json();

      if (data.success) {
        toast.success('┬íContrase├▒a cambiada exitosamente! ­ƒÄë', {
          duration: 4000,
          icon: 'Ô£à'
        });

        // Limpiar campos
        setNewPassword('');
        setConfirmPassword('');

        // Callback de ├®xito
        onSuccess();
      } else {
        setErrors({ general: data.error || 'Error al cambiar la contrase├▒a' });
        toast.error(data.error || 'Error al cambiar la contrase├▒a');
      }
    } catch (error) {
      console.error('Error:', error);
      setErrors({ general: 'Error de conexi├│n. Intenta nuevamente.' });
      toast.error('Error de conexi├│n');
    } finally {
      setIsLoading(false);
    }
  };

  const handleLogout = () => {
    if (onLogout) {
      onLogout();
    }
  };

  if (!isOpen) return null;

  const passwordStrength = getPasswordStrength();
  const strengthPercentage = (passwordStrength / passwordCriteria.length) * 100;

  return (
    <AnimatePresence>
      <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
        {/* Backdrop - NO CLICKABLE */}
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="absolute inset-0 bg-black/90 backdrop-blur-lg"
        />

        {/* Modal */}
        <motion.div
          initial={{ opacity: 0, scale: 0.95, y: 20 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.95, y: 20 }}
          transition={{ type: "spring", duration: 0.5 }}
          className="relative w-full max-w-2xl max-h-[90vh] overflow-y-auto"
          onClick={(e) => e.stopPropagation()}
        >
          <div
            className="relative rounded-3xl p-8 backdrop-blur-xl border border-amber-500/30 shadow-2xl overflow-hidden"
            style={{
              background: `
                linear-gradient(135deg,
                  rgba(245, 158, 11, 0.1) 0%,
                  rgba(251, 146, 60, 0.1) 50%,
                  rgba(239, 68, 68, 0.1) 100%
                )
              `
            }}
          >
            {/* Header */}
            <div className="text-center mb-8">
              <motion.div
                initial={{ scale: 0 }}
                animate={{ scale: 1 }}
                transition={{ delay: 0.2, type: "spring" }}
                className="w-20 h-20 mx-auto mb-6 bg-gradient-to-r from-amber-500 to-orange-600 rounded-full flex items-center justify-center shadow-lg"
              >
                <Shield className="w-10 h-10 text-white" />
              </motion.div>

              <h2 className="text-3xl font-bold text-white mb-3">
                ­ƒöÆ Configuraci├│n de Seguridad Obligatoria
              </h2>
              <p className="text-amber-200/90 text-lg mb-2">
                Por tu seguridad, debes establecer una contrase├▒a personalizada
              </p>
              <p className="text-amber-200/70 text-sm">
                Actualmente usas tu NIF como contrase├▒a, lo cual no es seguro
              </p>
            </div>

            {/* Alert importante */}
            <motion.div
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: 0.3 }}
              className="mb-6 p-4 bg-amber-500/20 border border-amber-500/40 rounded-xl flex items-start gap-3"
            >
              <AlertCircle className="w-5 h-5 text-amber-400 flex-shrink-0 mt-0.5" />
              <div>
                <p className="text-amber-200 text-sm font-semibold mb-1">
                  Importante: Este proceso es obligatorio
                </p>
                <p className="text-amber-200/80 text-xs">
                  No podr├ís acceder al ├írea de clientes hasta que establezcas una contrase├▒a segura. 
                  Esta medida protege tu informaci├│n y cumple con nuestras pol├¡ticas de seguridad.
                </p>
              </div>
            </motion.div>

            {/* Error general */}
            {errors.general && (
              <motion.div
                initial={{ opacity: 0, y: -10 }}
                animate={{ opacity: 1, y: 0 }}
                className="mb-6 p-4 bg-red-500/10 border border-red-500/30 rounded-xl flex items-start gap-3"
              >
                <AlertCircle className="w-5 h-5 text-red-400 flex-shrink-0 mt-0.5" />
                <p className="text-red-200 text-sm">{errors.general}</p>
              </motion.div>
            )}

            {/* Form */}
            <form onSubmit={handleSubmit} className="space-y-6">
              {/* Nueva Contrase├▒a */}
              <div>
                <label htmlFor="newPassword" className="block text-sm font-medium text-amber-200 mb-2">
                  Nueva Contrase├▒a Segura
                </label>
                <div className="relative">
                  <Lock className="absolute left-3 top-1/2 transform -translate-y-1/2 text-amber-300 w-5 h-5" />
                  <Input
                    id="newPassword"
                    type={showNewPassword ? 'text' : 'password'}
                    value={newPassword}
                    onChange={(e) => {
                      setNewPassword(e.target.value);
                      setErrors(prev => ({ ...prev, newPassword: undefined, general: undefined }));
                    }}
                    placeholder="Crea una contrase├▒a fuerte"
                    className={`pl-10 pr-12 py-3 bg-black/30 border text-white placeholder-amber-300/50 focus:border-amber-300 rounded-xl ${
                      errors.newPassword ? 'border-red-500/50 focus:border-red-400' : 'border-amber-400/30'
                    }`}
                    disabled={isLoading}
                    autoComplete="new-password"
                  />
                  <button
                    type="button"
                    onClick={() => setShowNewPassword(!showNewPassword)}
                    className="absolute right-3 top-1/2 transform -translate-y-1/2 text-amber-300 hover:text-amber-200 transition-colors"
                    tabIndex={-1}
                  >
                    {showNewPassword ? (
                      <EyeOff className="w-5 h-5" />
                    ) : (
                      <Eye className="w-5 h-5" />
                    )}
                  </button>
                </div>

                {/* Barra de fortaleza */}
                {newPassword && (
                  <div className="mt-3">
                    <div className="flex items-center justify-between mb-2">
                      <span className="text-xs text-amber-200/70">Fortaleza de la contrase├▒a</span>
                      <span className="text-xs font-semibold text-amber-200">
                        {passwordStrength}/{passwordCriteria.length}
                      </span>
                    </div>
                    <div className="h-2 bg-black/30 rounded-full overflow-hidden">
                      <motion.div
                        initial={{ width: 0 }}
                        animate={{ width: `${strengthPercentage}%` }}
                        className={`h-full transition-colors duration-300 ${
                          strengthPercentage < 40 ? 'bg-red-500' :
                          strengthPercentage < 80 ? 'bg-yellow-500' :
                          'bg-green-500'
                        }`}
                      />
                    </div>
                  </div>
                )}

                {/* Criterios de validaci├│n */}
                <div className="mt-4 space-y-2">
                  {passwordCriteria.map((criterion) => {
                    const isValid = criterion.test(newPassword);
                    return (
                      <motion.div
                        key={criterion.id}
                        initial={{ opacity: 0, x: -10 }}
                        animate={{ opacity: 1, x: 0 }}
                        className="flex items-center gap-2"
                      >
                        {isValid ? (
                          <Check className="w-4 h-4 text-green-400" />
                        ) : (
                          <X className="w-4 h-4 text-gray-500" />
                        )}
                        <span className={`text-xs ${isValid ? 'text-green-300' : 'text-gray-400'}`}>
                          {criterion.label}
                        </span>
                      </motion.div>
                    );
                  })}
                </div>

                {errors.newPassword && (
                  <motion.p
                    initial={{ opacity: 0, y: -5 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="mt-2 text-sm text-red-400 flex items-center gap-1"
                  >
                    <AlertCircle className="w-4 h-4" />
                    {errors.newPassword}
                  </motion.p>
                )}
              </div>

              {/* Confirmar Contrase├▒a */}
              <div>
                <label htmlFor="confirmPassword" className="block text-sm font-medium text-amber-200 mb-2">
                  Confirmar Nueva Contrase├▒a
                </label>
                <div className="relative">
                  <Lock className="absolute left-3 top-1/2 transform -translate-y-1/2 text-amber-300 w-5 h-5" />
                  <Input
                    id="confirmPassword"
                    type={showConfirmPassword ? 'text' : 'password'}
                    value={confirmPassword}
                    onChange={(e) => {
                      setConfirmPassword(e.target.value);
                      setErrors(prev => ({ ...prev, confirmPassword: undefined, general: undefined }));
                    }}
                    placeholder="Repite tu nueva contrase├▒a"
                    className={`pl-10 pr-12 py-3 bg-black/30 border text-white placeholder-amber-300/50 focus:border-amber-300 rounded-xl ${
                      errors.confirmPassword ? 'border-red-500/50 focus:border-red-400' : 'border-amber-400/30'
                    }`}
                    disabled={isLoading}
                    autoComplete="new-password"
                  />
                  <button
                    type="button"
                    onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                    className="absolute right-3 top-1/2 transform -translate-y-1/2 text-amber-300 hover:text-amber-200 transition-colors"
                    tabIndex={-1}
                  >
                    {showConfirmPassword ? (
                      <EyeOff className="w-5 h-5" />
                    ) : (
                      <Eye className="w-5 h-5" />
                    )}
                  </button>
                </div>
                
                {/* Indicador de coincidencia */}
                {confirmPassword && (
                  <div className="mt-2 flex items-center gap-2">
                    {newPassword === confirmPassword ? (
                      <>
                        <Check className="w-4 h-4 text-green-400" />
                        <span className="text-xs text-green-300">Las contrase├▒as coinciden</span>
                      </>
                    ) : (
                      <>
                        <X className="w-4 h-4 text-red-400" />
                        <span className="text-xs text-red-300">Las contrase├▒as no coinciden</span>
                      </>
                    )}
                  </div>
                )}

                {errors.confirmPassword && (
                  <motion.p
                    initial={{ opacity: 0, y: -5 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="mt-2 text-sm text-red-400 flex items-center gap-1"
                  >
                    <AlertCircle className="w-4 h-4" />
                    {errors.confirmPassword}
                  </motion.p>
                )}
              </div>

              {/* Botones */}
              <div className="flex gap-3 pt-4">
                <Button
                  type="submit"
                  disabled={isLoading || passwordStrength < passwordCriteria.length}
                  className="flex-1 bg-gradient-to-r from-amber-500 to-orange-600 hover:from-amber-600 hover:to-orange-700 text-white font-semibold py-3 rounded-xl transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {isLoading ? (
                    <span className="flex items-center justify-center gap-2">
                      <Loader2 className="w-5 h-5 animate-spin" />
                      Cambiando contrase├▒a...
                    </span>
                  ) : (
                    'Establecer Contrase├▒a Segura'
                  )}
                </Button>

                {onLogout && (
                  <Button
                    type="button"
                    onClick={handleLogout}
                    disabled={isLoading}
                    variant="outline"
                    className="bg-black/20 border-amber-500/30 text-amber-200 hover:bg-black/30 hover:border-amber-500/50 px-6 py-3 rounded-xl"
                  >
                    Cerrar Sesi├│n
                  </Button>
                )}
              </div>
            </form>

            {/* Footer info */}
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 0.5 }}
              className="mt-6 p-4 bg-blue-500/10 border border-blue-500/30 rounded-xl"
            >
              <p className="text-blue-200/80 text-xs text-center">
                ­ƒÆí <strong>Consejo:</strong> Usa una combinaci├│n ├║nica de letras, n├║meros y s├¡mbolos. 
                No compartas esta contrase├▒a con nadie ni la uses en otros sitios.
              </p>
            </motion.div>
          </div>
        </motion.div>
      </div>
    </AnimatePresence>
  );
}

"use client";

import { useEffect, useState } from "react";
import { X, BookOpen, Download } from "lucide-react"; // Icons
import { motion, AnimatePresence } from "framer-motion";

interface CatalogModalProps {
    isOpen: boolean;
    onClose: () => void;
    pdfUrl: string;
    title?: string;
    edition?: string;
}

export const CatalogModal = ({
    isOpen,
    onClose,
    pdfUrl,
    title = "Cat├ílogo - Revista Mensual",
    edition = "Edici├│n Febrero 2026",
}: CatalogModalProps) => {
    // Lock body scroll when open
    useEffect(() => {
        if (isOpen) {
            document.body.style.overflow = "hidden";
        } else {
            document.body.style.overflow = "unset";
        }
        return () => {
            document.body.style.overflow = "unset";
        };
    }, [isOpen]);

    return (
        <AnimatePresence>
            {isOpen && (
                <>
                    {/* Backdrop */}
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        onClick={onClose}
                        className="fixed inset-0 z-[100] bg-black/80 backdrop-blur-sm transition-all"
                    />

                    {/* Modal Container */}
                    <motion.div
                        initial={{ opacity: 0, scale: 0.9, y: 20 }}
                        animate={{ opacity: 1, scale: 1, y: 0 }}
                        exit={{ opacity: 0, scale: 0.9, y: 20 }}
                        transition={{ type: "spring", duration: 0.5 }}
                        className="fixed inset-0 z-[100] flex items-center justify-center p-4 sm:p-6"
                    >
                        <div className="relative w-full max-w-6xl h-[90vh] bg-white rounded-2xl shadow-2xl overflow-hidden flex flex-col border border-border/50">

                            {/* Header Bar */}
                            <div className="flex items-center justify-between px-6 py-4 bg-primary text-primary-foreground select-none">
                                <div className="flex items-center gap-3">
                                    <div className="p-2 bg-white/20 rounded-full">
                                        <BookOpen className="w-5 h-5" />
                                    </div>
                                    <div>
                                        <h3 className="font-bold text-lg leading-tight">{title}</h3>
                                        <p className="text-xs text-primary-foreground/80 font-medium tracking-wide uppercase">
                                            {edition}
                                        </p>
                                    </div>
                                </div>

                                <div className="flex items-center gap-2">
                                    <a
                                        href={pdfUrl}
                                        download
                                        className="p-2 hover:bg-white/20 rounded-full transition-colors flex items-center gap-2 text-sm font-medium mr-2"
                                        title="Descargar PDF"
                                    >
                                        <Download className="w-4 h-4" />
                                        <span className="hidden sm:inline">Descargar</span>
                                    </a>

                                    <button
                                        onClick={onClose}
                                        className="p-2 hover:bg-white/20 rounded-full transition-colors"
                                    >
                                        <X className="w-6 h-6" />
                                    </button>
                                </div>
                            </div>

                            {/* PDF Viewer (Iframe) */}
                            <div className="flex-1 bg-gray-100 relative w-full h-full">
                                <iframe
                                    src={`${pdfUrl}#view=FitH`}
                                    className="w-full h-full"
                                    title="PDF Viewer"
                                    frameBorder="0"
                                />
                            </div>

                        </div>
                    </motion.div>
                </>
            )}
        </AnimatePresence>
    );
};

'use client';

import { useEffect, useState, useMemo } from 'react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  LineElement,
  PointElement,
  ArcElement,
  Title,
  Tooltip,
  Legend,
  Filler
} from 'chart.js';
import { Bar, Line, Doughnut } from 'react-chartjs-2';
import { motion } from 'framer-motion';
import { TrendingUp, Package, BarChart3, PieChart } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { secureFetch } from '@/lib/secureFetch'; // ­ƒöÉ HttpOnly Cookie Auth

// Registrar componentes de Chart.js
ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  LineElement,
  PointElement,
  ArcElement,
  Title,
  Tooltip,
  Legend,
  Filler
);

interface EstadisticasFacturas {
  year: number;
  total: number;
  pagadas: number;
  pendientes: number;
  totalPagadas: number;
  totalPendientes: number;
}

interface TopProducto {
  codigo: string;
  nombre: string;
  cantidad: number;
  importe: number;
  pedidos: number;
}

interface DashboardChartsProps {
  codigoCliente: string;
}

export function DashboardCharts({ codigoCliente }: DashboardChartsProps) {
  const [estadisticas, setEstadisticas] = useState<EstadisticasFacturas[]>([]);
  const [topProductos, setTopProductos] = useState<TopProducto[]>([]);
  const [loadingStats, setLoadingStats] = useState(true);
  const [loadingProducts, setLoadingProducts] = useState(true);
  const [error, setError] = useState<string>('');
  const [isMobile, setIsMobile] = useState(false);

  // Detectar si es m├│vil para ajustar opciones de gr├íficos
  useEffect(() => {
    const checkMobile = () => {
      setIsMobile(window.innerWidth < 768);
    };
    
    checkMobile();
    window.addEventListener('resize', checkMobile);
    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  useEffect(() => {
    if (!codigoCliente) return;

    // Evitar m├║ltiples llamadas con un flag
    let isCancelled = false;

    const cargarDatos = async () => {
      try {
        // ­ƒöÉ SEGURIDAD: Usar secureFetch con HttpOnly cookies
        // Cargar estad├¡sticas
        setLoadingStats(true);
        const { data: statsData, ok: statsOk } = await secureFetch<{ success: boolean; estadisticas: any[] }>(
          `/api/auth/estadisticas/${codigoCliente}`
        );

        if (isCancelled) return;

        if (statsOk && statsData.success && Array.isArray(statsData.estadisticas)) {
          // Mapear los nombres de columnas del backend (MAY├ÜSCULAS) a camelCase
          const estadisticasMapeadas = statsData.estadisticas.map((stat: any) => ({
            year: stat.YEAR || stat.year,
            total: stat.TOTAL || stat.total || 0,
            pagadas: stat.PAGADAS || stat.pagadas || 0,
            pendientes: stat.PENDIENTES || stat.pendientes || 0,
            totalPagadas: stat.TOTALPAGADAS || stat.totalPagadas || 0,
            totalPendientes: stat.TOTALPENDIENTES || stat.totalPendientes || 0
          }));
          console.log('­ƒôè Estad├¡sticas procesadas:', estadisticasMapeadas);
          setEstadisticas(estadisticasMapeadas);
        } else {
          console.warn('ÔÜá´©Å No se pudieron cargar las estad├¡sticas');
          setEstadisticas([]);
        }
        setLoadingStats(false);

        // Cargar top productos
        setLoadingProducts(true);
        const { data: productsData, ok: productsOk } = await secureFetch<{ success: boolean; productos: any[] }>(
          `/api/auth/top-productos/${codigoCliente}?limite=10`
        );

        if (isCancelled) return;

        if (productsOk && productsData.success && Array.isArray(productsData.productos)) {
          // Mapear los nombres de columnas del backend (MAY├ÜSCULAS) a camelCase
          const productosMapeados = productsData.productos.map((prod: any) => ({
            codigo: (prod.CODIGOARTICULO || prod.codigo || '').trim(),
            nombre: (prod.DESCRIPCION || prod.nombre || 'Sin nombre').trim(),
            cantidad: prod.CANTIDADTOTAL || prod.cantidad || 0,
            importe: prod.IMPORTETOTAL || prod.importe || 0,
            pedidos: prod.NUMEROFACTURAS || prod.pedidos || 0
          }));
          console.log('­ƒôª Productos procesados:', productosMapeados);
          setTopProductos(productosMapeados);
        } else {
          console.warn('ÔÜá´©Å No se pudieron cargar los productos');
          setTopProductos([]);
        }
        setLoadingProducts(false);

      } catch (error) {
        if (isCancelled) return;
        console.error('ÔØî Error cargando datos de gr├íficos:', error);
        setError('Error al cargar los datos');
        setEstadisticas([]);
        setTopProductos([]);
        setLoadingStats(false);
        setLoadingProducts(false);
      }
    };

    cargarDatos();

    // Cleanup para evitar memory leaks
    return () => {
      isCancelled = true;
    };
  }, [codigoCliente]);

  // Configuraci├│n del gr├ífico de facturas (Bar Chart) - TOTAL POR A├æO
  const facturasChartData = useMemo(() => ({
    labels: estadisticas.length > 0 ? estadisticas.map(e => e.year.toString()) : [],
    datasets: [
      {
        label: 'Total Facturas',
        data: estadisticas.length > 0 ? estadisticas.map(e => e.total || 0) : [],
        backgroundColor: 'rgba(59, 130, 246, 0.85)', // Azul m├ís s├│lido
        borderColor: 'rgba(37, 99, 235, 1)', // Borde m├ís oscuro
        borderWidth: isMobile ? 2 : 3,
        borderRadius: isMobile ? 6 : 12,
        barThickness: isMobile ? 28 : 50, // Barras m├ís delgadas en m├│vil
        maxBarThickness: isMobile ? 35 : 60,
        hoverBackgroundColor: 'rgba(37, 99, 235, 0.95)',
        hoverBorderColor: 'rgba(29, 78, 216, 1)',
        hoverBorderWidth: isMobile ? 2 : 4
      }
      // DATASET DE PAGADAS/PENDIENTES COMENTADO - NO ELIMINAR
      // {
      //   label: 'Facturas Pagadas',
      //   data: estadisticas.map(e => e.pagadas),
      //   backgroundColor: 'rgba(16, 185, 129, 0.8)',
      //   borderColor: 'rgba(16, 185, 129, 1)',
      //   borderWidth: 2,
      //   borderRadius: 8,
      //   barThickness: 40
      // },
      // {
      //   label: 'Facturas Pendientes',
      //   data: estadisticas.map(e => e.pendientes),
      //   backgroundColor: 'rgba(251, 146, 60, 0.8)',
      //   borderColor: 'rgba(251, 146, 60, 1)',
      //   borderWidth: 2,
      //   borderRadius: 8,
      //   barThickness: 40
      // }
    ]
  }), [estadisticas, isMobile]);

  const facturasChartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    interaction: {
      mode: 'index' as const,
      intersect: false,
    },
    animation: {
      duration: 1500,
      easing: 'easeInOutQuart' as const,
      delay: (context: any) => {
        return context.dataIndex * 150;
      }
    },
    plugins: {
      legend: {
        position: 'top' as const,
        align: 'start' as const,
        labels: {
          font: {
            size: isMobile ? 11 : 15,
            weight: 'bold' as const,
            family: "'Inter', 'system-ui', '-apple-system', 'sans-serif'"
          },
          padding: isMobile ? 10 : 20,
          usePointStyle: true,
          pointStyle: 'circle',
          color: '#1e293b',
          boxWidth: isMobile ? 8 : 10,
          boxHeight: isMobile ? 8 : 10
        }
      },
      title: {
        display: false
      },
      tooltip: {
        enabled: true,
        backgroundColor: 'rgba(15, 23, 42, 0.95)',
        titleFont: {
          size: isMobile ? 12 : 16,
          weight: 'bold' as const,
          family: "'Inter', 'system-ui', '-apple-system', 'sans-serif'"
        },
        bodyFont: {
          size: isMobile ? 11 : 14,
          weight: 'normal' as const,
          family: "'Inter', 'system-ui', '-apple-system', 'sans-serif'"
        },
        padding: isMobile ? 10 : 16,
        cornerRadius: 12,
        displayColors: true,
        borderColor: 'rgba(59, 130, 246, 0.5)',
        borderWidth: 2,
        caretSize: 8,
        caretPadding: 10,
        callbacks: {
          label: function(context: any) {
            let label = context.dataset.label || '';
            if (label) {
              label += ': ';
            }
            if (context.parsed.y !== null) {
              label += context.parsed.y + ' facturas';
            }
            return label;
          }
        }
      }
    },
    scales: {
      x: {
        grid: {
          display: false,
          drawBorder: false
        },
        ticks: {
          font: {
            size: isMobile ? 11 : 14,
            weight: 'bold' as const,
            family: "'Inter', 'system-ui', '-apple-system', 'sans-serif'"
          },
          color: '#475569',
          padding: isMobile ? 5 : 10
        }
      },
      y: {
        beginAtZero: true,
        grid: {
          color: 'rgba(148, 163, 184, 0.15)',
          drawBorder: false,
          lineWidth: 1.5
        },
        ticks: {
          font: {
            size: isMobile ? 10 : 13,
            weight: 'normal' as const,
            family: "'Inter', 'system-ui', '-apple-system', 'sans-serif'"
          },
          color: '#64748b',
          precision: 0,
          padding: isMobile ? 5 : 10
        }
      }
    }
  };

  // Configuraci├│n del gr├ífico de importes (Line Chart)
  const importesChartData = useMemo(() => ({
    labels: estadisticas.length > 0 ? estadisticas.map(e => e.year.toString()) : [],
    datasets: [
      {
        label: 'Importe Pagado',
        data: estadisticas.length > 0 ? estadisticas.map(e => e.totalPagadas || 0) : [],
        backgroundColor: 'rgba(59, 130, 246, 0.15)',
        borderColor: 'rgba(37, 99, 235, 1)',
        borderWidth: 4,
        fill: true,
        tension: 0.45,
        pointRadius: 7,
        pointHoverRadius: 10,
        pointBackgroundColor: '#fff',
        pointBorderColor: 'rgba(37, 99, 235, 1)',
        pointBorderWidth: 4,
        pointHoverBackgroundColor: 'rgba(59, 130, 246, 1)',
        pointHoverBorderColor: '#fff',
        pointHoverBorderWidth: 3
      },
      {
        label: 'Importe Pendiente',
        data: estadisticas.length > 0 ? estadisticas.map(e => e.totalPendientes || 0) : [],
        backgroundColor: 'rgba(239, 68, 68, 0.15)',
        borderColor: 'rgba(220, 38, 38, 1)',
        borderWidth: 4,
        fill: true,
        tension: 0.45,
        pointRadius: 7,
        pointHoverRadius: 10,
        pointBackgroundColor: '#fff',
        pointBorderColor: 'rgba(220, 38, 38, 1)',
        pointBorderWidth: 4,
        pointHoverBackgroundColor: 'rgba(239, 68, 68, 1)',
        pointHoverBorderColor: '#fff',
        pointHoverBorderWidth: 3
      }
    ]
  }), [estadisticas, isMobile]);

  const importesChartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    interaction: {
      mode: 'index' as const,
      intersect: false,
    },
    animation: {
      duration: 1800,
      easing: 'easeInOutCubic' as const,
      delay: (context: any) => {
        return context.dataIndex * 200;
      }
    },
    plugins: {
      legend: {
        position: 'top' as const,
        align: (isMobile ? 'center' : 'start') as 'center' | 'start',
        labels: {
          font: {
            size: isMobile ? 10 : 15,
            weight: 'bold' as const,
            family: "'Inter', 'system-ui', '-apple-system', 'sans-serif'"
          },
          padding: isMobile ? 8 : 20,
          usePointStyle: true,
          pointStyle: 'circle',
          color: '#1e293b',
          boxWidth: isMobile ? 8 : 10,
          boxHeight: isMobile ? 8 : 10
        }
      },
      tooltip: {
        enabled: true,
        backgroundColor: 'rgba(15, 23, 42, 0.95)',
        titleFont: {
          size: isMobile ? 12 : 16,
          weight: 'bold' as const,
          family: "'Inter', 'system-ui', '-apple-system', 'sans-serif'"
        },
        bodyFont: {
          size: isMobile ? 11 : 14,
          weight: 'normal' as const,
          family: "'Inter', 'system-ui', '-apple-system', 'sans-serif'"
        },
        padding: isMobile ? 10 : 16,
        cornerRadius: 12,
        displayColors: true,
        borderColor: 'rgba(59, 130, 246, 0.5)',
        borderWidth: 2,
        caretSize: 8,
        caretPadding: 10,
        callbacks: {
          label: function(context: any) {
            let label = context.dataset.label || '';
            if (label) {
              label += ': ';
            }
            if (context.parsed.y !== null) {
              label += new Intl.NumberFormat('es-ES', {
                style: 'currency',
                currency: 'EUR'
              }).format(context.parsed.y);
            }
            return label;
          }
        }
      }
    },
    scales: {
      x: {
        grid: {
          display: false,
          drawBorder: false
        },
        ticks: {
          font: {
            size: isMobile ? 11 : 14,
            weight: 'bold' as const,
            family: "'Inter', 'system-ui', '-apple-system', 'sans-serif'"
          },
          color: '#475569',
          padding: isMobile ? 5 : 10
        }
      },
      y: {
        beginAtZero: true,
        grid: {
          color: 'rgba(148, 163, 184, 0.15)',
          drawBorder: false,
          lineWidth: 1.5
        },
        ticks: {
          font: {
            size: isMobile ? 9 : 13,
            weight: 'normal' as const,
            family: "'Inter', 'system-ui', '-apple-system', 'sans-serif'"
          },
          color: '#64748b',
          padding: isMobile ? 5 : 10,
          callback: function(value: any) {
            // En m├│vil formato m├ís corto
            if (isMobile) {
              return (value / 1000).toFixed(0) + 'kÔé¼';
            }
            return new Intl.NumberFormat('es-ES', {
              style: 'currency',
              currency: 'EUR',
              minimumFractionDigits: 0,
              maximumFractionDigits: 0
            }).format(value);
          }
        }
      }
    }
  };

  // Configuraci├│n del gr├ífico de productos (Doughnut Chart)
  const productosChartData = useMemo(() => ({
    labels: topProductos.length > 0 ? topProductos.map(p => p.nombre && p.nombre.length > 30 ? p.nombre.substring(0, 30) + '...' : p.nombre || 'Sin nombre') : [],
    datasets: [
      {
        label: 'Importe Total',
        data: topProductos.length > 0 ? topProductos.map(p => p.importe || 0) : [],
        backgroundColor: [
          'rgba(59, 130, 246, 0.8)',
          'rgba(16, 185, 129, 0.8)',
          'rgba(251, 146, 60, 0.8)',
          'rgba(139, 92, 246, 0.8)',
          'rgba(236, 72, 153, 0.8)',
          'rgba(34, 197, 94, 0.8)',
          'rgba(249, 115, 22, 0.8)',
          'rgba(168, 85, 247, 0.8)',
          'rgba(244, 63, 94, 0.8)',
          'rgba(14, 165, 233, 0.8)'
        ],
        borderColor: [
          'rgba(59, 130, 246, 1)',
          'rgba(16, 185, 129, 1)',
          'rgba(251, 146, 60, 1)',
          'rgba(139, 92, 246, 1)',
          'rgba(236, 72, 153, 1)',
          'rgba(34, 197, 94, 1)',
          'rgba(249, 115, 22, 1)',
          'rgba(168, 85, 247, 1)',
          'rgba(244, 63, 94, 1)',
          'rgba(14, 165, 233, 1)'
        ],
        borderWidth: 3,
        hoverOffset: 10
      }
    ]
  }), [topProductos, isMobile]);

  const productosChartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    animation: {
      duration: 2000,
      easing: 'easeInOutQuart' as const,
      animateRotate: true,
      animateScale: true
    },
    plugins: {
      legend: {
        // En m├│vil: leyenda abajo con texto m├ís peque├▒o
        // En desktop: leyenda a la derecha
        position: (isMobile ? 'bottom' : 'right') as 'bottom' | 'right',
        labels: {
          font: {
            size: isMobile ? 10 : 12,
            weight: 'normal' as const,
            family: "'Inter', 'system-ui', '-apple-system', 'sans-serif'"
          },
          padding: isMobile ? 8 : 15,
          usePointStyle: true,
          pointStyle: 'circle',
          color: '#334155',
          boxWidth: isMobile ? 8 : 12,
          boxHeight: isMobile ? 8 : 12,
          generateLabels: (chart: any) => {
            const data = chart.data;
            if (data.labels.length && data.datasets.length) {
              return data.labels.map((label: string, i: number) => {
                const value = data.datasets[0].data[i];
                const formatted = new Intl.NumberFormat('es-ES', {
                  style: 'currency',
                  currency: 'EUR',
                  minimumFractionDigits: 0,
                  maximumFractionDigits: 0
                }).format(value);
                // En m├│vil acortar nombres
                const displayLabel = isMobile && label.length > 15 
                  ? label.substring(0, 15) + '...' 
                  : label;
                return {
                  text: isMobile ? displayLabel : `${label} (${formatted})`,
                  fillStyle: data.datasets[0].backgroundColor[i],
                  hidden: false,
                  index: i,
                  fontColor: '#334155'
                };
              });
            }
            return [];
          }
        }
      },
      tooltip: {
        enabled: true,
        backgroundColor: 'rgba(15, 23, 42, 0.95)',
        titleFont: {
          size: 15,
          weight: 'bold' as const,
          family: "'Inter', 'system-ui', '-apple-system', 'sans-serif'"
        },
        bodyFont: {
          size: 13,
          weight: 'normal' as const,
          family: "'Inter', 'system-ui', '-apple-system', 'sans-serif'"
        },
        padding: 14,
        cornerRadius: 12,
        displayColors: true,
        borderColor: 'rgba(59, 130, 246, 0.5)',
        borderWidth: 2,
        caretSize: 8,
        callbacks: {
          label: function(context: any) {
            const producto = topProductos[context.dataIndex];
            return [
              `Importe: ${new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR' }).format(producto.importe)}`,
              `Cantidad: ${producto.cantidad} unidades`,
              `Pedidos: ${producto.pedidos}`
            ];
          }
        }
      }
    }
  };

  if (loadingStats && loadingProducts) {
    return (
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {[1, 2].map((i) => (
          <Card key={i} className="border-0 shadow-lg">
            <CardHeader>
              <div className="h-6 bg-gray-200 dark:bg-gray-700 rounded w-1/2 animate-pulse"></div>
            </CardHeader>
            <CardContent>
              <div className="h-64 bg-gray-100 dark:bg-gray-800 rounded animate-pulse"></div>
            </CardContent>
          </Card>
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Gr├íficos de Facturas */}
      <div className="grid grid-cols-1 xl:grid-cols-2 gap-4 md:gap-6">
        {/* Gr├ífico de Cantidad de Facturas */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
        >
          <Card className="border-0 shadow-lg bg-gradient-to-br from-white to-blue-50/30 dark:from-gray-800 dark:to-gray-750">
            <CardHeader className="pb-2 md:pb-4">
              <CardTitle className="flex items-center justify-between text-base md:text-lg">
                <div className="flex items-center">
                  <BarChart3 className="w-4 h-4 md:w-5 md:h-5 mr-2 text-blue-600 dark:text-blue-400" />
                  <span className="text-sm md:text-base">Facturas por A├▒o</span>
                </div>
                {!loadingStats && estadisticas.length > 0 && (
                  <span className="text-xs md:text-sm font-normal text-gray-500 dark:text-gray-400">
                    ├Ültimos {estadisticas.length} a├▒os
                  </span>
                )}
              </CardTitle>
            </CardHeader>
            <CardContent className="pt-0">
              {loadingStats ? (
                <div className="h-48 md:h-64 flex items-center justify-center">
                  <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
                </div>
              ) : estadisticas.length > 0 ? (
                <div className="h-48 md:h-64">
                  <Bar data={facturasChartData} options={facturasChartOptions} />
                </div>
              ) : (
                <div className="h-48 md:h-64 flex items-center justify-center text-gray-500 dark:text-gray-400">
                  No hay datos disponibles
                </div>
              )}
            </CardContent>
          </Card>
        </motion.div>

        {/* Gr├ífico de Importes */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3 }}
        >
          <Card className="border-0 shadow-lg bg-gradient-to-br from-white to-emerald-50/30 dark:from-gray-800 dark:to-gray-750">
            <CardHeader className="pb-2 md:pb-4">
              <CardTitle className="flex items-center justify-between text-base md:text-lg">
                <div className="flex items-center">
                  <TrendingUp className="w-4 h-4 md:w-5 md:h-5 mr-2 text-emerald-600 dark:text-emerald-400" />
                  <span className="text-sm md:text-base">Evoluci├│n de Importes</span>
                </div>
                {!loadingStats && estadisticas.length > 0 && (
                  <span className="text-xs md:text-sm font-normal text-gray-500 dark:text-gray-400">
                    Hist├│rico
                  </span>
                )}
              </CardTitle>
            </CardHeader>
            <CardContent className="pt-0">
              {loadingStats ? (
                <div className="h-48 md:h-64 flex items-center justify-center">
                  <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-emerald-600"></div>
                </div>
              ) : estadisticas.length > 0 ? (
                <div className="h-48 md:h-64">
                  <Line data={importesChartData} options={importesChartOptions} />
                </div>
              ) : (
                <div className="h-48 md:h-64 flex items-center justify-center text-gray-500 dark:text-gray-400">
                  No hay datos disponibles
                </div>
              )}
            </CardContent>
          </Card>
        </motion.div>
      </div>

      {/* Gr├ífico de Top Productos */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.4 }}
      >
        <Card className="border-0 shadow-lg bg-gradient-to-br from-white to-purple-50/30 dark:from-gray-800 dark:to-gray-750">
          <CardHeader className="pb-2 md:pb-4">
            <CardTitle className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2 text-base md:text-lg">
              <div className="flex items-center">
                <PieChart className="w-4 h-4 md:w-5 md:h-5 mr-2 text-purple-600 dark:text-purple-400" />
                <span className="text-sm md:text-base">Top 10 Productos</span>
              </div>
              {!loadingProducts && topProductos.length > 0 && (
                <span className="text-xs md:text-sm font-normal text-gray-500 dark:text-gray-400">
                  ├Ültimos 2 a├▒os
                </span>
              )}
            </CardTitle>
          </CardHeader>
          <CardContent className="pt-0">
            {loadingProducts ? (
              <div className="h-64 md:h-80 flex items-center justify-center">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-purple-600"></div>
              </div>
            ) : topProductos.length > 0 ? (
              <div className="h-[320px] md:h-80">
                <Doughnut data={productosChartData} options={productosChartOptions} />
              </div>
            ) : (
              <div className="h-64 md:h-80 flex items-center justify-center text-gray-500 dark:text-gray-400">
                <div className="text-center">
                  <Package className="w-10 h-10 md:w-12 md:h-12 mx-auto mb-2 text-gray-400 dark:text-gray-600" />
                  <p className="text-sm md:text-base">No hay datos de productos disponibles</p>
                </div>
              </div>
            )}
          </CardContent>
        </Card>
      </motion.div>
    </div>
  );
}

