    }

    // ========== MILESTONES ==========
    const achieved: Array<{ id: string; label: string; date: string }> = [];

    if (totalFacturas >= 1) achieved.push({ id: 'first-order', label: 'Primera factura', date: primeraFactura || '' });
    if (totalFacturado >= 1000) achieved.push({ id: '1k', label: '1.000Ôé¼ facturados', date: '' });
    if (totalFacturado >= 5000) achieved.push({ id: '5k', label: '5.000Ôé¼ facturados', date: '' });
    if (totalFacturado >= 10000) achieved.push({ id: '10k', label: '10.000Ôé¼ facturados', date: '' });
    if (rachaActiva >= 3) achieved.push({ id: 'streak-3', label: '3 meses seguidos', date: '' });
