    let nextMilestone = { id: 'first-order', label: 'Primera factura', progress: 0 };
    if (totalFacturas >= 1 && totalFacturado < 1000) {
      nextMilestone = { id: '1k', label: '1.000Ôé¼ facturados', progress: (totalFacturado / 1000) * 100 };
