  const generatePdfBlob = useCallback(async (factura: FacturaBackend): Promise<string> => {
    // Crear clave ├║nica para la factura (corregido: usar campos que existen)
    const cacheKey = `${factura.serieFactura}-${factura.numeroFactura}-${factura.ejercicio}`;

    // Si ya est├í en cach├®, devolverlo
    if (pdfCache[cacheKey]) {
      console.log('Ô£à PDF recuperado de cach├®:', cacheKey);
      return pdfCache[cacheKey];
    }

    setLoadingPdf(true);
    try {
      console.log('­ƒöä Generando PDF:', cacheKey);

      const response = await apiClient.post('/api/generar-factura', {
        serie: factura.serieFactura || factura.serie,
        numero: factura.numeroFactura || factura.numero,
        ejercicio: factura.ejercicio
      }, {
        responseType: 'blob',
        timeout: 30000 // Timeout de 30 segundos
      });

      const blob = response.data;

      if (blob.size === 0) {
        throw new Error('PDF vac├¡o recibido del servidor');
      }

      const blobUrl = URL.createObjectURL(blob);
      console.log('Ô£à PDF generado exitosamente:', cacheKey);

      // Limitar cach├® a 2 PDFs m├íximo (FIFO - First In, First Out)
      setPdfCache(prev => {
        const entries = Object.entries(prev);

        // Si ya tenemos 2 PDFs, eliminar el m├ís antiguo
        if (entries.length >= 2) {
          const [oldestKey, oldestUrl] = entries[0];
          URL.revokeObjectURL(oldestUrl); // Liberar memoria del blob antiguo
          console.log('­ƒùæ´©Å Eliminado PDF antiguo de cach├®:', oldestKey);

          // Devolver solo el segundo PDF y el nuevo
          const [, ...remaining] = entries;
          return {
            ...Object.fromEntries(remaining),
            [cacheKey]: blobUrl
          };
        }

        return {
          ...prev,
          [cacheKey]: blobUrl
        };
      });

      return blobUrl;
    } catch (error: any) {
      console.error('ÔØî Error generando PDF:', error);
      const errorMsg = error.name === 'AbortError'
        ? 'Tiempo de espera agotado. Intenta de nuevo.'
        : error.message || 'Error desconocido al generar PDF';
      toast.error(`Error al generar PDF: ${errorMsg}`);
      throw error;
    } finally {
      setLoadingPdf(false);
    }
  }, [pdfCache]);

