'use client';

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Eye, EyeOff, Lock, AlertCircle, CheckCircle, Shield, Clock, Key } from 'lucide-react';
import { toast } from 'sonner';
import { secureFetch } from '@/lib/secureFetch';
import { useAuthStore } from '@/lib/store';

interface PasswordChangeFormProps {
  isOpen: boolean;
  onClose: () => void;
}

export function PasswordChangeForm({ isOpen, onClose }: PasswordChangeFormProps) {
  const { user } = useAuthStore();
  const [step, setStep] = useState<'check' | 'request' | 'verify'>('check');
  const [loading, setLoading] = useState(false);

  // Cooldown check states
  const [canChange, setCanChange] = useState(false);
  const [daysRemaining, setDaysRemaining] = useState(0);
  const [lastChangeDate, setLastChangeDate] = useState<string>('');
  const [isLegacy, setIsLegacy] = useState(false);

  // Request code states
  const [maskedEmail, setMaskedEmail] = useState('');
  const [verificationCode, setVerificationCode] = useState('');

  // Password states
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  // Password strength
  const [passwordStrength, setPasswordStrength] = useState<number>(0);
  const [passwordFeedback, setPasswordFeedback] = useState<string>('');

  // Check if user can change password (30-day cooldown)
  useEffect(() => {
    if (isOpen && step === 'check') {
      checkPasswordChangeCooldown();
    }
  }, [isOpen, step]);

  const checkPasswordChangeCooldown = async () => {
    setLoading(true);
    try {
      // Use codigoCliente from user.id (defined in AuthStore)
      const codigoCliente = user?.id || user?.codigoCliente || user?.customerCode || user?.code;
      if (!codigoCliente) {
        toast.error('No se encontr├│ el c├│digo de cliente');
        // onClose(); // Keep open to see error
        return;
      }

      // Add timestamp to prevent caching (304 Not Modified issues)
      const response = await secureFetch(`/api/auth/v2/verificar-cambio/${codigoCliente}?_=${Date.now()}`);
      const data = response.data as any; // secureFetch already parses JSON

      if (response.ok && (data.ok || data.success)) {
        setCanChange(data.canChange);
        setDaysRemaining(data.daysRemaining || 0);
        setLastChangeDate(data.lastChangeDate || '');
        setIsLegacy(data.isLegacy || false);

        if (data.canChange) {
          // Can proceed to request code
          setStep('request');
        } else {
          // Show cooldown message
          setStep('check');
        }
      } else {
        toast.error(data.message || 'Error al verificar permisos de cambio');
        // onClose(); // Keep open to see error
      }
    } catch (error) {
      console.error('Error checking cooldown:', error);
      toast.error('Error al verificar permisos de cambio');
      // onClose(); // Keep open to see error
    } finally {
      setLoading(false);
    }
  };

  const requestVerificationCode = async () => {
    setLoading(true);
    try {
      // Use codigoCliente from user.id (defined in AuthStore)
      const codigoCliente = user?.id || user?.codigoCliente || user?.customerCode || user?.code;
      if (!codigoCliente) {
        toast.error('No se encontr├│ el c├│digo de cliente');
        return;
      }

      const response = await secureFetch('/api/auth/v2/solicitar-codigo', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ codigoCliente })
      });

      const data = response.data as any; // secureFetch already parses JSON

      if (response.ok && (data.ok || data.success)) {
        setMaskedEmail(data.maskedEmail || '');
        toast.success('C├│digo de verificaci├│n generado');

        // In dev mode, show the code
        if (data.codigoVerificacion) {
          toast.info(`C├│digo de prueba: ${data.codigoVerificacion}`, { duration: 10000 });
        }

        setStep('verify');
      } else {
        toast.error(data.message || 'Error al solicitar c├│digo de verificaci├│n');
      }
    } catch (error) {
      console.error('Error requesting code:', error);
      toast.error('Error al solicitar c├│digo de verificaci├│n');
    } finally {
      setLoading(false);
    }
  };

  const verifyAndChangePassword = async () => {
    // Validations
    if (!verificationCode || verificationCode.length !== 6) {
      toast.error('Ingrese un c├│digo de verificaci├│n v├ílido (6 d├¡gitos)');
      return;
    }

    if (!newPassword || newPassword.length < 12) {
      toast.error('La contrase├▒a debe tener al menos 12 caracteres');
      return;
    }

    if (newPassword !== confirmPassword) {
      toast.error('Las contrase├▒as no coinciden');
      return;
    }

    if (passwordStrength < 4) {
      toast.error('La contrase├▒a es muy d├®bil. Por favor, elige una contrase├▒a m├ís segura.');
      return;
    }

    setLoading(true);
    try {
      // Use codigoCliente from user.id (defined in AuthStore)
      const codigoCliente = user?.id || user?.codigoCliente || user?.customerCode || user?.code;
      if (!codigoCliente) {
        toast.error('No se encontr├│ el c├│digo de cliente');
        return;
      }

      const response = await secureFetch('/api/auth/v2/verificar-codigo', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          codigoCliente,
          codigoVerificacion: verificationCode,
          nuevaPassword: newPassword
        })
      });

      const data = response.data as any; // secureFetch already parses JSON

      if (response.ok && (data.ok || data.success)) {
        toast.success('Contrase├▒a cambiada exitosamente');
        onClose();
      } else {
        toast.error(data.message || 'Error al cambiar la contrase├▒a');
      }
    } catch (error) {
      console.error('Error changing password:', error);
      toast.error('Error al cambiar la contrase├▒a');
    } finally {
      setLoading(false);
    }
  };

  // Simple password strength check (client-side only, real check is on backend)
  useEffect(() => {
    if (!newPassword) {
      setPasswordStrength(0);
      setPasswordFeedback('');
      return;
    }

    let strength = 0;
    let feedback = '';

    // Length check
    if (newPassword.length >= 12) strength++;
    if (newPassword.length >= 16) strength++;

    // Complexity checks
    if (/[a-z]/.test(newPassword)) strength++;
    if (/[A-Z]/.test(newPassword)) strength++;
    if (/[0-9]/.test(newPassword)) strength++;
    if (/[^a-zA-Z0-9]/.test(newPassword)) strength++;

    // Normalize to 0-4 scale
    if (strength >= 6) strength = 4;
    else if (strength >= 5) strength = 3;
    else if (strength >= 4) strength = 2;
    else if (strength >= 2) strength = 1;
    else strength = 0;

    // Feedback
    if (strength === 0) feedback = 'Muy d├®bil';
    else if (strength === 1) feedback = 'D├®bil';
    else if (strength === 2) feedback = 'Aceptable';
    else if (strength === 3) feedback = 'Fuerte';
    else feedback = 'Muy fuerte';

    setPasswordStrength(strength);
    setPasswordFeedback(feedback);
  }, [newPassword]);

  const handleClose = () => {
    // Reset all states
    setStep('check');
    setCanChange(false);
    setDaysRemaining(0);
    setLastChangeDate('');
    setIsLegacy(false);
    setMaskedEmail('');
    setVerificationCode('');
    setNewPassword('');
    setConfirmPassword('');
    setShowPassword(false);
    setShowConfirmPassword(false);
    setPasswordStrength(0);
    setPasswordFeedback('');
    onClose();
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <>
          {/* Backdrop */}
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={handleClose}
            className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50"
          />

          {/* Modal */}
          <div className="fixed inset-0 flex items-center justify-center z-50 p-4">
            <motion.div
              initial={{ opacity: 0, scale: 0.95, y: 20 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95, y: 20 }}
              className="bg-white rounded-3xl shadow-2xl max-w-md w-full max-h-[90vh] overflow-y-auto"
              onClick={(e) => e.stopPropagation()}
            >
              {/* Header */}
              <div className="relative overflow-hidden">
                <div className="h-2 bg-gradient-to-r from-emerald-500 via-teal-500 to-cyan-500" />
                <div className="p-6 pb-4">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-emerald-500 to-teal-600 flex items-center justify-center shadow-lg">
                        <Shield className="w-6 h-6 text-white" />
                      </div>
                      <div>
                        <h2 className="text-2xl font-bold text-gray-900">Cambiar Contrase├▒a</h2>
                        <p className="text-sm text-gray-500">Actualiza tu contrase├▒a de forma segura</p>
                      </div>
                    </div>
                    <button
                      onClick={handleClose}
                      className="w-10 h-10 rounded-xl bg-gray-100 hover:bg-gray-200 flex items-center justify-center transition-colors"
                    >
                      <X className="w-5 h-5 text-gray-600" />
                    </button>
                  </div>
                </div>
              </div>

              {/* Content */}
              <div className="p-6 pt-2">
                {/* Step 1: Cooldown Check */}
                {step === 'check' && (
                  <div className="space-y-6">
                    {loading ? (
                      <div className="flex flex-col items-center justify-center py-12">
                        <div className="w-16 h-16 rounded-full border-4 border-emerald-100 border-t-emerald-500 animate-spin mb-4" />
                        <p className="text-gray-600">Verificando permisos...</p>
                      </div>
                    ) : !canChange ? (
                      daysRemaining > 0 ? (
                        <div className="space-y-4">
                          {/* Cooldown Warning */}
                          <div className="p-4 bg-amber-50 border-2 border-amber-200 rounded-xl">
                            <div className="flex items-start gap-3">
                              <Clock className="w-6 h-6 text-amber-600 flex-shrink-0 mt-0.5" />
                              <div>
                                <h3 className="font-bold text-amber-900 mb-1">Per├¡odo de Espera Activo</h3>
                                <p className="text-sm text-amber-800 leading-relaxed">
                                  Por seguridad, solo puedes cambiar tu contrase├▒a una vez cada 30 d├¡as.
                                </p>
                              </div>
                            </div>
                          </div>

                          {/* Details */}
                          <div className="space-y-3">
                            <div className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                              <span className="text-sm font-medium text-gray-700">├Ültimo cambio:</span>
                              <span className="text-sm font-bold text-gray-900">
                                {lastChangeDate ? new Date(lastChangeDate).toLocaleDateString('es-ES') : 'Nunca'}
                              </span>
                            </div>
                            <div className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                              <span className="text-sm font-medium text-gray-700">D├¡as restantes:</span>
                              <span className="text-sm font-bold text-amber-600">
                                {daysRemaining} {daysRemaining === 1 ? 'd├¡a' : 'd├¡as'}
                              </span>
                            </div>
                          </div>

                          {/* Close Button */}
                          <button
                            onClick={handleClose}
                            className="w-full py-3.5 bg-gray-600 hover:bg-gray-700 text-white font-bold rounded-xl transition-colors"
                          >
                            Entendido
                          </button>
                        </div>
                      ) : (
                        <div className="space-y-6 text-center py-8">
                          <div className="mx-auto w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mb-4">
                            <X className="w-8 h-8 text-red-600" />
                          </div>
                          <div>
                            <h3 className="text-lg font-bold text-gray-900 mb-2">No se pudo verificar el permiso</h3>
                            <p className="text-gray-500">
                              Ocurri├│ un error al verificar el estado de su cuenta. Por favor contacte con soporte.
                            </p>
                          </div>
                          <button
                            onClick={handleClose}
                            className="px-6 py-2 bg-gray-900 text-white rounded-xl hover:bg-gray-800 transition-colors"
                          >
                            Cerrar
                          </button>
                        </div>
                      )
                    ) : null}
                  </div>
                )}

                {/* Step 2: Request Verification Code */}
                {step === 'request' && (
                  <div className="space-y-6">
                    <div className="p-4 bg-blue-50 border-2 border-blue-200 rounded-xl">
                      <div className="flex items-start gap-3">
                        <AlertCircle className="w-6 h-6 text-blue-600 flex-shrink-0 mt-0.5" />
                        <div>
                          <h3 className="font-bold text-blue-900 mb-1">Verificaci├│n Requerida</h3>
                          <p className="text-sm text-blue-800 leading-relaxed">
                            Para cambiar tu contrase├▒a, necesitas un c├│digo de verificaci├│n.
                          </p>
                        </div>
                      </div>
                    </div>

                    <button
                      onClick={requestVerificationCode}
                      disabled={loading}
                      className="w-full py-4 bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-700 hover:to-teal-700 disabled:from-gray-400 disabled:to-gray-400 text-white font-bold rounded-xl transition-all flex items-center justify-center gap-2 shadow-lg"
                    >
                      {loading ? (
                        <>
                          <div className="w-5 h-5 rounded-full border-2 border-white/30 border-t-white animate-spin" />
                          Generando c├│digo...
                        </>
                      ) : (
                        <>
                          <Key className="w-5 h-5" />
                          Solicitar C├│digo de Verificaci├│n
                        </>
                      )}
                    </button>

                    <button
                      onClick={handleClose}
                      className="w-full py-3 text-gray-600 hover:text-gray-800 font-medium transition-colors"
                    >
                      Cancelar
                    </button>
                  </div>
                )}

                {/* Step 3: Verify Code & Change Password */}
                {step === 'verify' && (
                  <div className="space-y-6">
                    {/* Email Info */}
                    {maskedEmail && (
                      <div className="p-4 bg-emerald-50 border-2 border-emerald-200 rounded-xl">
                        <div className="flex items-start gap-3">
                          <CheckCircle className="w-6 h-6 text-emerald-600 flex-shrink-0 mt-0.5" />
                          <div>
                            <h3 className="font-bold text-emerald-900 mb-1">C├│digo Generado</h3>
                            <p className="text-sm text-emerald-800">
                              Se ha generado un c├│digo de verificaci├│n para <strong>{maskedEmail}</strong>
                            </p>
                          </div>
                        </div>
                      </div>
                    )}

                    {/* Verification Code Input */}
                    <div className="space-y-2">
                      <label className="block text-sm font-semibold text-gray-700">
                        C├│digo de Verificaci├│n (6 d├¡gitos)
                      </label>
                      <input
                        type="text"
                        value={verificationCode}
                        onChange={(e) => setVerificationCode(e.target.value.replace(/\D/g, '').slice(0, 6))}
                        placeholder="123456"
                        maxLength={6}
                        className="w-full px-4 py-3.5 border-2 border-gray-200 focus:border-emerald-500 focus:ring-4 focus:ring-emerald-100 rounded-xl text-center text-2xl font-mono tracking-widest transition-all"
                      />
                    </div>

                    {/* New Password Input */}
                    <div className="space-y-2">
                      <label className="block text-sm font-semibold text-gray-700">
                        Nueva Contrase├▒a
                      </label>
                      <div className="relative">
                        <input
                          type={showPassword ? 'text' : 'password'}
                          value={newPassword}
                          onChange={(e) => setNewPassword(e.target.value)}
                          placeholder="M├¡nimo 12 caracteres"
                          className="w-full px-4 py-3.5 pr-12 border-2 border-gray-200 focus:border-emerald-500 focus:ring-4 focus:ring-emerald-100 rounded-xl transition-all"
                        />
                        <button
                          type="button"
                          onClick={() => setShowPassword(!showPassword)}
                          className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                        >
                          {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                        </button>
                      </div>

                      {/* Password Strength Indicator */}
                      {newPassword && (
                        <div className="space-y-2">
                          <div className="flex gap-1">
                            {[1, 2, 3, 4].map((level) => (
                              <div
                                key={level}
                                className={`h-1.5 flex-1 rounded-full transition-colors ${passwordStrength >= level
                                  ? passwordStrength === 1
                                    ? 'bg-red-500'
                                    : passwordStrength === 2
                                      ? 'bg-orange-500'
                                      : passwordStrength === 3
                                        ? 'bg-yellow-500'
                                        : 'bg-emerald-500'
                                  : 'bg-gray-200'
                                  }`}
                              />
                            ))}
                          </div>
                          <p className={`text-xs font-medium ${passwordStrength === 0 ? 'text-gray-500' :
                            passwordStrength === 1 ? 'text-red-600' :
                              passwordStrength === 2 ? 'text-orange-600' :
                                passwordStrength === 3 ? 'text-yellow-600' :
                                  'text-emerald-600'
                            }`}>
                            Fortaleza: {passwordFeedback}
                          </p>
                        </div>
                      )}
                    </div>

                    {/* Confirm Password Input */}
                    <div className="space-y-2">
                      <label className="block text-sm font-semibold text-gray-700">
                        Confirmar Nueva Contrase├▒a
                      </label>
                      <div className="relative">
                        <input
                          type={showConfirmPassword ? 'text' : 'password'}
                          value={confirmPassword}
                          onChange={(e) => setConfirmPassword(e.target.value)}
                          placeholder="Repite la contrase├▒a"
                          className="w-full px-4 py-3.5 pr-12 border-2 border-gray-200 focus:border-emerald-500 focus:ring-4 focus:ring-emerald-100 rounded-xl transition-all"
                        />
                        <button
                          type="button"
                          onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                          className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                        >
                          {showConfirmPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                        </button>
                      </div>

                      {/* Match Indicator */}
                      {confirmPassword && (
                        <p className={`text-xs font-medium ${newPassword === confirmPassword ? 'text-emerald-600' : 'text-red-600'
                          }`}>
                          {newPassword === confirmPassword ? 'Ô£ô Las contrase├▒as coinciden' : 'Ô£ù Las contrase├▒as no coinciden'}
                        </p>
                      )}
                    </div>

                    {/* Submit Button */}
                    <button
                      onClick={verifyAndChangePassword}
                      disabled={loading || !verificationCode || !newPassword || !confirmPassword || passwordStrength < 4}
                      className="w-full py-4 bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-700 hover:to-teal-700 disabled:from-gray-400 disabled:to-gray-400 text-white font-bold rounded-xl transition-all flex items-center justify-center gap-2 shadow-lg disabled:cursor-not-allowed"
                    >
                      {loading ? (
                        <>
                          <div className="w-5 h-5 rounded-full border-2 border-white/30 border-t-white animate-spin" />
                          Cambiando contrase├▒a...
                        </>
                      ) : (
                        <>
                          <CheckCircle className="w-5 h-5" />
                          Cambiar Contrase├▒a
                        </>
                      )}
                    </button>

                    <button
                      onClick={handleClose}
                      className="w-full py-3 text-gray-600 hover:text-gray-800 font-medium transition-colors"
                    >
                      Cancelar
                    </button>
                  </div>
                )}
              </div>
            </motion.div>
          </div>
        </>
      )}
    </AnimatePresence>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Search,
  Filter,
  ShoppingCart,
  ChevronLeft,
  ChevronRight,
  Package,
  Tag,
  TrendingDown,
  Loader2,
  X
} from 'lucide-react';
import { useAuthStore, useCartStore } from '@/lib/store';
import { useSession } from '@/contexts/SessionContext';
import { formatCurrency } from '@/lib/utils';

interface Producto {
  codigo: string;
  descripcion: string;
  descripcionCorta: string;
  familia: {
    codigo: string;
    descripcion: string;
  };
  codigoIva: number;
  unidadMedida: string;
  unidadesCaja: number;
  peso: number;
  precios: {
    base: number;
    cliente: number | null;
    tarifaCliente: number | null;
    tieneDescuento: boolean;
  };
}

interface Familia {
  codigo: string;
  descripcion: string;
  totalProductos: number;
}

export default function ProductsCatalog() {
  const [productos, setProductos] = useState<Producto[]>([]);
  const [familias, setFamilias] = useState<Familia[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadingFamilias, setLoadingFamilias] = useState(true);
  const [busqueda, setBusqueda] = useState('');
  const [familiaSeleccionada, setFamiliaSeleccionada] = useState<string | null>(null);
  const [paginaActual, setPaginaActual] = useState(1);
  const [totalPaginas, setTotalPaginas] = useState(1);
  const [totalProductos, setTotalProductos] = useState(0);
  const [showFilters, setShowFilters] = useState(false);

  const { isAuthenticated } = useAuthStore();
  const { cliente } = useSession();
  const addToCart = useCartStore((state) => state.addItem);

  // API base URL (vac├¡o = rutas relativas manejadas por Next.js rewrites)
  const API_URL = '';

  // Cargar familias
  useEffect(() => {
    const fetchFamilias = async () => {
      try {
        const response = await fetch(`${API_URL}/api/productos/familias`);
        const data = await response.json();
        if (data.success) {
          setFamilias(data.data);
        }
      } catch (error) {
        console.error('Error cargando familias:', error);
      } finally {
        setLoadingFamilias(false);
      }
    };

    fetchFamilias();
  }, [API_URL]);

  // Cargar productos
  const cargarProductos = useCallback(async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams({
        pagina: paginaActual.toString(),
        limite: '24',
        ...(busqueda && { busqueda }),
        ...(familiaSeleccionada && { familia: familiaSeleccionada })
      });

      // ­ƒöÉ SECURITY: Usar fetch con credentials para enviar cookies HttpOnly
      const response = await fetch(`${API_URL}/api/productos?${params}`, { 
        headers: {
          'Content-Type': 'application/json'
        },
        credentials: 'include' // ­ƒöÉ Env├¡a cookies HttpOnly autom├íticamente
      });
      const data = await response.json();

      if (data.success) {
        setProductos(data.data);
        setTotalPaginas(data.pagination.totalPaginas);
        setTotalProductos(data.pagination.totalProductos);
      }
    } catch (error) {
      console.error('Error cargando productos:', error);
    } finally {
      setLoading(false);
    }
  }, [API_URL, paginaActual, busqueda, familiaSeleccionada, isAuthenticated]);

  useEffect(() => {
    cargarProductos();
  }, [cargarProductos]);

  // Buscar con debounce
  useEffect(() => {
    const timer = setTimeout(() => {
      setPaginaActual(1);
    }, 500);

    return () => clearTimeout(timer);
  }, [busqueda]);

  const handleAddToCart = (producto: Producto) => {
    const precio = producto.precios.cliente || producto.precios.base;
    const productToAdd: any = {
      id: producto.codigo,
      name: producto.descripcionCorta || producto.descripcion,
      price: precio,
      image: "/kage/brand/logo-alpha.png",
      inStock: true,
      category: producto.familia?.descripcion || 'Otros'
    };
    addToCart(productToAdd, 1);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 dark:from-gray-900 dark:to-gray-800">
      {/* Header del Cat├ílogo */}
      <div className="bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 sticky top-0 z-10 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4">
            {/* T├¡tulo */}
            <div>
              <h1 className="text-3xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                <Package className="h-8 w-8 text-green-600 dark:text-green-400" />
                Nuestros Productos
              </h1>
              <p className="text-gray-600 dark:text-gray-400 mt-1">
                {totalProductos.toLocaleString()} productos disponibles
                {isAuthenticated && (
                  <span className="ml-2 text-green-600 dark:text-green-400 font-medium">
                    ÔÇó Precios personalizados
                  </span>
                )}
              </p>
            </div>

            {/* Buscador */}
            <div className="flex-1 max-w-md">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-gray-400" />
                <input
                  type="text"
                  value={busqueda}
                  onChange={(e) => setBusqueda(e.target.value)}
                  placeholder="Buscar productos..."
                  className="w-full pl-10 pr-4 py-3 rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-green-500 dark:focus:ring-green-400 focus:border-transparent transition-all"
                />
                {busqueda && (
                  <button
                    onClick={() => setBusqueda('')}
                    className="absolute right-3 top-1/2 transform -translate-y-1/2"
                  >
                    <X className="h-5 w-5 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300" />
                  </button>
                )}
              </div>
            </div>

