  const [open, setOpen] = useState(false),
    [enabled, setEnabled] = useState(false),
    [error, setError] = useState("");
  const dialog = useRef<HTMLDialogElement>(null),
    bannerConfigure = useRef<HTMLButtonElement>(null),
    source = useRef<HTMLElement | null>(null),
    handoff = useRef(false),
    openRef = useRef(false);
  openRef.current = open;
  useEffect(() => {
    setChoice(getAnalyticsConsent());
    return subscribeAnalyticsConsent(setChoice);
  }, []);
  useEffect(() => {
    const show = (event: Event) => {
      source.current =
        (event as CustomEvent<{ source?: HTMLElement }>).detail?.source ||
        (document.activeElement as HTMLElement | null);
      setEnabled(getAnalyticsConsent()?.analytics === true);
      setError("");
      handoff.current = false;
      window.dispatchEvent(
        new CustomEvent("kage:overlay-open", { detail: { id: "cookies" } }),
      );
      setOpen(true);
    };
    const other = (event: Event) => {
      const id = (event as CustomEvent<{ id?: string }>).detail?.id;
      if (id && id !== "cookies" && openRef.current) {
        handoff.current = true;
        setOpen(false);
      }
    };
    window.addEventListener("kage:cookie-preferences", show);
    window.addEventListener("kage:overlay-open", other);
    return () => {
      window.removeEventListener("kage:cookie-preferences", show);
      window.removeEventListener("kage:overlay-open", other);
    };
  }, []);
  useEffect(() => {
    const element = dialog.current;
    if (!open || !element) return;
    const returnTarget = source.current;
    const release = isolateBackground(
      Array.from(
        document.querySelectorAll<HTMLElement>("[data-kage-background],#nav"),
      ),
    );
    document.documentElement.classList.add("kage-cookie-open");
    if (typeof element.showModal === "function") element.showModal();
    else element.setAttribute("open", "");
    element
      .querySelector<HTMLInputElement>("input:not(:disabled)")
      ?.focus({ preventScroll: true });
    return () => {
      release();
      document.documentElement.classList.remove("kage-cookie-open");
      if (element.open) {
        if (typeof element.close === "function") element.close();
        else element.removeAttribute("open");
      }
      window.dispatchEvent(
        new CustomEvent("kage:overlay-close", { detail: { id: "cookies" } }),
      );
      const target = returnTarget?.isConnected
        ? returnTarget
        : bannerConfigure.current || document.getElementById("main-content");
      if (!handoff.current) target?.focus({ preventScroll: true });
    };
  }, [open]);
  const choose = (analytics: boolean, fromDialog = false) => {
    const result = setAnalyticsConsent(analytics);
    setChoice(result.choice);
    if (!result.stored) {
      setError(copy.error);
      return;
    }
    setError("");
    if (fromDialog) setOpen(false);
    toast.success(copy.saved);
  };
  const showPreferences = (event: React.MouseEvent<HTMLButtonElement>) =>
    window.dispatchEvent(
      new CustomEvent("kage:cookie-preferences", {
        detail: { source: event.currentTarget },
      }),
    );
  const trap = (event: React.KeyboardEvent<HTMLDialogElement>) => {
    if (event.key !== "Tab") return;
    const elements = Array.from(
      event.currentTarget.querySelectorAll<HTMLElement>(
        "button:not(:disabled),input:not(:disabled),a[href]",
      ),
    );
    const first = elements[0],
      last = elements[elements.length - 1];
    if (!first) return;
    if (event.shiftKey && document.activeElement === first) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault();
      first.focus();
    }
  };
  return (
    <>
      {!open && choice !== undefined && (choice === null || Boolean(error)) ? (
        <aside
          className="kage-cookie-banner"
          data-kage-cookie-banner
          aria-labelledby="kage-cookie-banner-title"
          data-fx="form-feedback"
        >
          <h2 id="kage-cookie-banner-title">{copy.title}</h2>
          <p>{copy.summary}</p>
          {error ? <p role="alert">{error}</p> : null}
          <div className="kage-cookie-actions">
            <button type="button" onClick={() => choose(true)}>
              {copy.accept}
            </button>
            <button type="button" onClick={() => choose(false)}>
              {copy.reject}
            </button>
          </div>
          <button
            ref={bannerConfigure}
            type="button"
            className="kage-cookie-configure"
            onClick={showPreferences}
          >
            {copy.configure}
          </button>
          {error && choice ? (
            <button
              type="button"
              className="kage-cookie-configure"
              onClick={() => setError("")}
            >
              {copy.close}
            </button>
          ) : null}
        </aside>
      ) : null}
      <dialog
        ref={dialog}
        className="kage-cookie-dialog"
        role="dialog"
        aria-modal={open ? true : undefined}
        aria-labelledby="kage-cookie-title"
        aria-describedby="kage-cookie-description"
        data-kage-cookie-preferences
        data-state={open ? "open" : "closed"}
        data-fx="modal-motion form-feedback"
        onCancel={(event) => {
          event.preventDefault();
          setOpen(false);
        }}
        onClose={() => {
          if (!dialog.current?.open) setOpen(false);
        }}
        onKeyDown={trap}
      >
        <div className="kage-cookie-heading">
          <h2 id="kage-cookie-title">{copy.title}</h2>
          <button
            type="button"
            onClick={() => setOpen(false)}
            aria-label={copy.close}
          >
            ├ù
          </button>
        </div>
        <p id="kage-cookie-description">{copy.summary}</p>
        <form
          onSubmit={(event) => {
            event.preventDefault();
            choose(enabled, true);
          }}
        >
          <label className="kage-cookie-category">
            <input type="checkbox" checked disabled readOnly />
            <span>
              <strong>{copy.essential}</strong>
              <small>{copy.essentialHelp}</small>
            </span>
          </label>
          <label className="kage-cookie-category">
            <input
              type="checkbox"
              checked={enabled}
              onChange={(event) => setEnabled(event.currentTarget.checked)}
            />
            <span>
              <strong>{copy.analytics}</strong>
              <small>{copy.analyticsHelp}</small>
            </span>
          </label>
          {error ? <p role="alert">{error}</p> : null}
          <div className="kage-cookie-actions">
            <button type="submit">{copy.save}</button>
            <button type="button" onClick={() => setOpen(false)}>
              {copy.close}
            </button>
          </div>
        </form>
      </dialog>
    </>
  );
}

