"use client";
import { useEffect, useRef, useState, type ReactNode } from "react";
import { usePathname } from "next/navigation";
import {
  hasAnalyticsConsent,
  initAnalytics,
  stopAnalytics,
  subscribeAnalyticsConsent,
  trackNavigation,
} from "@/lib/analytics";
export function AnalyticsProvider({ children }: { children: ReactNode }) {
  const pathname = usePathname(),
    previous = useRef(pathname);
  const [allowed, setAllowed] = useState(false);
  useEffect(() => {
    const permitted = hasAnalyticsConsent();
    if (!permitted) stopAnalytics();
    setAllowed(permitted);
    return subscribeAnalyticsConsent((choice) =>
      setAllowed(choice?.analytics === true),
    );
  }, []);
  useEffect(() => (allowed ? initAnalytics() : undefined), [allowed]);
  useEffect(() => {
    if (allowed && pathname && previous.current !== pathname)
      trackNavigation(pathname);
    previous.current = pathname;
  }, [pathname, allowed]);
  return <>{children}</>;
}
export default AnalyticsProvider;

'use client';

import { useEffect } from 'react';
import { initializeGSAP, cleanupGSAP } from '@/lib/gsap-config';
import { usePathname } from 'next/navigation';

export function GSAPProvider({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();

  // Initialize GSAP globally
  useEffect(() => {
    const initialized = initializeGSAP();
    
    if (initialized) {
      console.log('Ô£à GSAP initialized with optimized scroll configuration');
    }

    // Cleanup on unmount (app-level cleanup)
    return () => {
      cleanupGSAP();
    };
  }, []);

  // Refresh ScrollTrigger on route changes
  useEffect(() => {
    // Small delay to ensure new page content is rendered
    const timer = setTimeout(() => {
      if (typeof window !== 'undefined') {
        const { ScrollTrigger } = require('gsap/ScrollTrigger');
        if (ScrollTrigger) {
          ScrollTrigger.refresh();
        }
      }
    }, 100);

    return () => clearTimeout(timer);
  }, [pathname]);

  return <>{children}</>;
}

'use client'

import { Suspense, ReactNode, ComponentType, lazy } from 'react'

interface LazyLoadingProviderProps {
  children: ReactNode
}

interface LazyComponentProps {
  Component: ComponentType<any>
  fallback?: ReactNode
  props?: any
}

const LazyLoadingSkeleton = () => (
  <div className="animate-pulse space-y-4">
    <div className="h-4 bg-gray-200 rounded w-3/4"></div>
    <div className="h-4 bg-gray-200 rounded w-1/2"></div>
    <div className="h-8 bg-gray-200 rounded w-full"></div>
  </div>
)

export const LazyComponent = ({ Component, fallback = <LazyLoadingSkeleton />, props = {} }: LazyComponentProps) => (
  <Suspense fallback={fallback}>
    <Component {...props} />
  </Suspense>
)

export const withLazyLoading = <P extends object>(
  Component: ComponentType<P>,
  fallback?: ReactNode
) => {
  const LazyWrapper = (props: P) => (
    <Suspense fallback={fallback || <LazyLoadingSkeleton />}>
      <Component {...props} />
    </Suspense>
  )

  LazyWrapper.displayName = `withLazyLoading(${Component.displayName || Component.name})`
  return LazyWrapper
}

export const dynamicImport = (importFn: () => Promise<{ default: ComponentType<any> }>) => {
  return lazy(importFn)
}

export function LazyLoadingProvider({ children }: LazyLoadingProviderProps) {
  return <>{children}</>
}

'use client'

import { ReactNode, useEffect } from 'react'

interface PerformanceProviderProps {
  children: ReactNode
}

export function PerformanceProvider({ children }: PerformanceProviderProps) {
  useEffect(() => {
    if (typeof window !== 'undefined') {
      const observer = new IntersectionObserver(
        (entries) => {
          entries.forEach((entry) => {
            if (entry.isIntersecting) {
              const element = entry.target as HTMLElement

              if (element.dataset.src) {
                const img = element as HTMLImageElement
                const src = img.dataset.src
                if (!src) return
                img.src = src
                img.onload = () => {
                  img.classList.add('loaded')
                  observer.unobserve(img)
                }
              }

              if (element.dataset.background) {
                element.style.backgroundImage = `url(${element.dataset.background})`
                element.classList.add('loaded')
                observer.unobserve(element)
              }
            }
          })
        },
        {
          rootMargin: '50px',
          threshold: 0.1
        }
      )

      const lazyElements = document.querySelectorAll('[data-src], [data-background]')
      lazyElements.forEach((el) => observer.observe(el))

      if ('requestIdleCallback' in window) {
        window.requestIdleCallback(() => {
          const fonts = [
            'https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap'
          ]

          fonts.forEach((font) => {
            const link = document.createElement('link')
            link.rel = 'preload'
            link.as = 'style'
            link.href = font
            document.head.appendChild(link)

            link.onload = () => {
              link.rel = 'stylesheet'
            }
          })
        })
      }

      const connection = (navigator as any).connection
      if (connection) {
        if (connection.effectiveType === '4g' || connection.downlink > 2) {
          document.documentElement.classList.add('fast-connection')
        } else {
          document.documentElement.classList.add('slow-connection')
        }
      }

      return () => {
        observer.disconnect()
      }
    }
  }, [])

  return <>{children}</>
}

