'use client';

import React from 'react';
import { motion } from 'framer-motion';
import { Button as UIButton, ButtonProps } from '@/components/ui/button';
import { useHapticFeedback, useTouchGestures, mobileAnimationConfig, getTouchClasses } from '@/lib/mobile-utils';
import { cn } from '@/lib/utils';

interface TouchOptimizedButtonProps extends ButtonProps {
  haptic?: boolean;
  touchSize?: 'small' | 'medium' | 'large';
  onLongPress?: () => void;
  loading?: boolean;
  ripple?: boolean;
}

/**
 * Bot├│n optimizado para dispositivos t├íctiles
 * Incluye feedback h├íptico, gestos t├íctiles y animaciones suaves
 */
export const TouchOptimizedButton: React.FC<TouchOptimizedButtonProps> = ({
  children,
  className,
  onClick,
  onLongPress,
  haptic = true,
  touchSize = 'medium',
  loading = false,
  ripple = true,
  disabled,
  ...props
}) => {
  const { triggerHaptic } = useHapticFeedback();
  const { isTouchDevice, createTouchHandler } = useTouchGestures();
  const [isPressed, setIsPressed] = React.useState(false);

  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (disabled || loading) return;
    
    // Feedback h├íptico
    if (haptic && isTouchDevice) {
      triggerHaptic('light');
    }
    
    onClick?.(e);
  };

  const touchHandlers = createTouchHandler(
    () => {
      if (disabled || loading) return;
      // Para touch, creamos un evento sint├®tico b├ísico
      const syntheticEvent = {
        preventDefault: () => {},
        stopPropagation: () => {},
      } as React.MouseEvent<HTMLButtonElement>;
      handleClick(syntheticEvent);
    },
    onLongPress ? () => {
      if (haptic && isTouchDevice) {
        triggerHaptic('medium');
      }
      onLongPress();
    } : undefined
  );

  return (
    <motion.div
      className="inline-block"
      {...mobileAnimationConfig.scaleOnTap}
      animate={loading ? { scale: 0.98 } : { scale: 1 }}
    >
      <UIButton
        {...props}
        className={cn(
          'touch-optimized mobile-optimized transition-all duration-200',
          getTouchClasses(touchSize),
          isPressed && 'scale-95',
          loading && 'pointer-events-none',
          className
        )}
        onClick={handleClick}
        disabled={disabled || loading}
        onMouseDown={() => setIsPressed(true)}
        onMouseUp={() => setIsPressed(false)}
        onMouseLeave={() => setIsPressed(false)}
        {...(isTouchDevice ? touchHandlers : {})}
      >
        {loading ? (
          <div className="flex items-center justify-center">
            <div className="w-4 h-4 border-2 border-current border-t-transparent rounded-full animate-spin mr-2" />
            <span>Cargando...</span>
          </div>
        ) : (
          children
        )}
      </UIButton>
    </motion.div>
  );
};

export default TouchOptimizedButton;

'use client';

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { useAuthStore } from '@/lib/store';
import { secureFetch } from '@/lib/secureFetch'; // ­ƒöÉ HttpOnly Cookie Auth
import { useSessionManager } from '@/hooks/useSessionManager'; // ­ƒöÉ Session manager

interface Cliente {
  codigo: string;
  nombre: string;
  empresa: string;
  email: string;
  telefono: string;
  direccion: {
    calle: string;
    poblacion: string;
    provincia: string;
    codigoPostal: string;
    completa: string;
  };
  nif: string;
}

interface SessionContextType {
  cliente: Cliente | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  refreshSession: () => Promise<void>;
}

const SessionContext = createContext<SessionContextType | undefined>(undefined);

export function SessionProvider({ children }: { children: React.ReactNode }) {
  const [cliente, setCliente] = useState<Cliente | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const { isAuthenticated, user } = useAuthStore();

  // ­ƒöÉ CR├ìTICO: Activar session manager para TODA la app
  // Esto detecta token expirado, monitorea inactividad, y hace logout autom├ítico
  useSessionManager({ enabled: true });

  const refreshSession = useCallback(async () => {
    // ­ƒöÉ SEGURIDAD: Ya no verificamos localStorage, usamos estado de auth store
    if (!isAuthenticated) {
      setCliente(null);
      setIsLoading(false);
      return;
    }

    try {
      setIsLoading(true);
      
      // ­ƒöÉ SEGURIDAD: Usar secureFetch con HttpOnly cookies
      const { data, ok } = await secureFetch<{ success: boolean; perfil: Cliente }>('/api/auth/perfil');

      if (ok && data.success && data.perfil) {
        setCliente(data.perfil);
      }
    } catch (error) {
      console.error('Error refreshing session:', error);
    } finally {
      setIsLoading(false);
    }
  }, [isAuthenticated]);

  // Cargar sesi├│n al montar o cuando cambie autenticaci├│n
  useEffect(() => {
    refreshSession();
  }, [refreshSession]);

  return (
    <SessionContext.Provider 
      value={{ 
        cliente, 
        isAuthenticated, 
        isLoading,
        refreshSession 
      }}
    >
      {children}
    </SessionContext.Provider>
  );
}

export function useSession() {
  const context = useContext(SessionContext);
  if (context === undefined) {
    throw new Error('useSession must be used within a SessionProvider');
  }
  return context;
}

