'use client';

import { useEffect, useRef, useState } from 'react';
import { gsap } from 'gsap';
import { useIntersectionObserver } from './use-intersection-observer';

interface UseAnimatedSectionOptions {
  threshold?: number;
  rootMargin?: string;
  animationDelay?: number;
  stagger?: number;
  freezeOnceVisible?: boolean;
}

export function useAnimatedSection(options: UseAnimatedSectionOptions = {}) {
  const [isReduced, setIsReduced] = useState(false);
  const [animationsReady, setAnimationsReady] = useState(false);
  const sectionRef = useRef<HTMLDivElement>(null);
  const timelineRef = useRef<gsap.core.Timeline | null>(null);
  
  const {
    threshold = 0.2,
    rootMargin = '50px',
    animationDelay = 100,
    stagger = 0.15,
    freezeOnceVisible = true
  } = options;

  // Check for reduced motion
  useEffect(() => {
    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
    setIsReduced(mediaQuery.matches);
    
    const handleChange = (e: MediaQueryListEvent) => setIsReduced(e.matches);
    mediaQuery.addEventListener('change', handleChange);
    
    return () => mediaQuery.removeEventListener('change', handleChange);
  }, []);

  // Use intersection observer
  const { targetRef, hasIntersected } = useIntersectionObserver({
    threshold,
    rootMargin,
    freezeOnceVisible
  });

  // Set the same ref for both section and intersection observer
  useEffect(() => {
    if (sectionRef.current && targetRef) {
      // @ts-ignore
      targetRef.current = sectionRef.current;
    }
  }, [targetRef]);

  // Trigger animations when element becomes visible
  useEffect(() => {
    if (!sectionRef.current || !hasIntersected || isReduced || animationsReady) return;

    const section = sectionRef.current;
    
    // Small delay to ensure DOM is stable
    const timer = setTimeout(() => {
      // Kill any existing timeline
      if (timelineRef.current) {
        timelineRef.current.kill();
      }

      // Create new timeline
      timelineRef.current = gsap.timeline({
        onComplete: () => setAnimationsReady(true)
      });

      // Find animated elements
      const titles = section.querySelectorAll('[data-animate="title"]');
      const cards = section.querySelectorAll('[data-animate="card"]');
      const content = section.querySelectorAll('[data-animate="content"]');

      // Animate titles
      if (titles.length > 0) {
        timelineRef.current.fromTo(titles, {
          opacity: 0,
          y: 60,
          scale: 0.9,
          rotationX: 45
        }, {
          opacity: 1,
          y: 0,
          scale: 1,
          rotationX: 0,
          duration: 1,
          ease: 'power3.out',
          stagger: stagger * 0.5
        });
      }

      // Animate content
      if (content.length > 0) {
        timelineRef.current.fromTo(content, {
          opacity: 0,
          y: 40,
          scale: 0.95
        }, {
          opacity: 1,
          y: 0,
          scale: 1,
          duration: 0.8,
          ease: 'power2.out',
          stagger: stagger * 0.3
        }, "-=0.5");
      }

      // Animate cards
      if (cards.length > 0) {
        timelineRef.current.fromTo(cards, {
          opacity: 0,
          y: 100,
          scale: 0.8,
          rotationY: 45
        }, {
          opacity: 1,
          y: 0,
          scale: 1,
          rotationY: 0,
          duration: 0.8,
          ease: 'power2.out',
          stagger: stagger
        }, "-=0.3");
      }
    }, animationDelay);

    return () => {
      clearTimeout(timer);
      if (timelineRef.current) {
        timelineRef.current.kill();
        timelineRef.current = null;
      }
    };
  }, [hasIntersected, isReduced, animationDelay, stagger, animationsReady]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (timelineRef.current) {
        timelineRef.current.kill();
      }
    };
  }, []);

  return {
    sectionRef,
    isIntersecting: hasIntersected,
    isReduced,
    animationsReady
  };
}

'use client';

import { useEffect, useState } from 'react';
import { deviceCapabilities } from '@/lib/mobile-utils';

/**
 * Hook para optimizar rendimiento en dispositivos m├│viles
 * Detecta capacidades del dispositivo y ajusta el comportamiento
 */
export const useMobileOptimization = () => {
  const [isMobile, setIsMobile] = useState(false);
  const [isLowPower, setIsLowPower] = useState(false);
  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);
  const [supportsHover, setSupportsHover] = useState(true);

  useEffect(() => {
    // Detectar si es m├│vil
    const checkMobile = () => setIsMobile(window.innerWidth < 768);
    checkMobile();
    
    // Detectar preferencias de movimiento
    setPrefersReducedMotion(deviceCapabilities.prefersReducedMotion());
    
    // Detectar soporte hover
    setSupportsHover(deviceCapabilities.supportsHover());
    
    // Detectar modo de bajo consumo
    deviceCapabilities.isLowPowerMode().then(setIsLowPower);

    // Listeners para cambios
    const mediaQuery = window.matchMedia('(max-width: 767px)');
    const motionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
    const hoverQuery = window.matchMedia('(hover: hover)');

    const handleResize = () => checkMobile();
    const handleMotionChange = () => setPrefersReducedMotion(motionQuery.matches);
    const handleHoverChange = () => setSupportsHover(hoverQuery.matches);

    window.addEventListener('resize', handleResize);
    motionQuery.addEventListener('change', handleMotionChange);
    hoverQuery.addEventListener('change', handleHoverChange);

    return () => {
      window.removeEventListener('resize', handleResize);
      motionQuery.removeEventListener('change', handleMotionChange);
      hoverQuery.removeEventListener('change', handleHoverChange);
    };
  }, []);

  // Configuraci├│n de animaciones optimizada
  const getAnimationConfig = () => ({
    shouldAnimate: !prefersReducedMotion && !isLowPower,
    reducedDuration: isLowPower || isMobile ? 0.2 : 0.3,
    disableParallax: isMobile || isLowPower,
    simplifyAnimations: isMobile || prefersReducedMotion,
    maxAnimations: isMobile ? 3 : 10, // Limitar animaciones simult├íneas en m├│vil
  });

  // Configuraci├│n de im├ígenes optimizada
  const getImageConfig = () => {
    let webpSupport = false;
    try {
      const canvas = document.createElement('canvas');
      const context = canvas.getContext('2d');
      webpSupport = context !== null && canvas.toDataURL('image/webp').indexOf('data:image/webp') === 0;
    } catch (e) {
      webpSupport = false;
    }

    return {
      lazyLoading: true,
      lowQuality: isLowPower,
      maxWidth: isMobile ? 800 : 1920,
      webpSupport,
    };
  };

  return {
    isMobile,
    isLowPower,
    prefersReducedMotion,
    supportsHover,
    isTouchDevice: deviceCapabilities.isTouchDevice(),
    animationConfig: getAnimationConfig(),
    imageConfig: getImageConfig(),
  };
};

/**
 * Hook para manejar scroll optimizado en m├│viles
 */
export const useMobileScroll = () => {
  const [isScrolling, setIsScrolling] = useState(false);
  const [scrollPosition, setScrollPosition] = useState(0);
  const { isMobile } = useMobileOptimization();

  useEffect(() => {
    let scrollTimeout: NodeJS.Timeout;

    const handleScroll = () => {
      setIsScrolling(true);
      setScrollPosition(window.scrollY);
      
      clearTimeout(scrollTimeout);
      scrollTimeout = setTimeout(() => {
        setIsScrolling(false);
      }, 150);
    };

    // Throttle scroll en m├│viles para mejor rendimiento
    let ticking = false;
    const throttledScroll = () => {
      if (!ticking) {
        requestAnimationFrame(() => {
          handleScroll();
          ticking = false;
        });
        ticking = true;
      }
    };

    window.addEventListener('scroll', throttledScroll, { passive: true });
    return () => {
      window.removeEventListener('scroll', throttledScroll);
      clearTimeout(scrollTimeout);
    };
  }, []);

  const scrollToTop = () => {
    window.scrollTo({
      top: 0,
      behavior: isMobile ? 'auto' : 'smooth' // Scroll inmediato en m├│vil
    });
  };

  const scrollToElement = (elementId: string) => {
    const element = document.getElementById(elementId);
    if (element) {
      const offset = isMobile ? 80 : 100; // Offset para header
      const top = element.offsetTop - offset;
      
      window.scrollTo({
        top,
        behavior: isMobile ? 'auto' : 'smooth'
      });
    }
  };

  return {
    isScrolling,
    scrollPosition,
    scrollToTop,
    scrollToElement,
  };
};

/**
 * Hook para manejar intersection observer optimizado
 */
export const useMobileIntersection = (options?: IntersectionObserverInit) => {
  const [isVisible, setIsVisible] = useState(false);
  const { isMobile } = useMobileOptimization();

  const defaultOptions: IntersectionObserverInit = {
    threshold: isMobile ? 0.1 : 0.3, // Threshold menor en m├│vil
    rootMargin: isMobile ? '0px 0px -50px 0px' : '0px 0px -100px 0px',
    ...options,
  };

  const ref = (node: Element | null) => {
    if (node) {
      const observer = new IntersectionObserver(
        ([entry]) => setIsVisible(entry.isIntersecting),
        defaultOptions
      );
      observer.observe(node);
      return () => observer.disconnect();
    }
  };

  return [ref, isVisible] as const;
};

export default useMobileOptimization;

