import { useEffect, useState, useCallback } from 'react';

interface ServiceWorkerState {
  isSupported: boolean;
  isRegistered: boolean;
  isOnline: boolean;
  registration: ServiceWorkerRegistration | null;
  updateAvailable: boolean;
}

interface UseServiceWorkerReturn extends ServiceWorkerState {
  update: () => Promise<void>;
  unregister: () => Promise<boolean>;
  clearCache: () => Promise<boolean>;
  getCacheSize: () => Promise<number>;
}

/**
 * Hook para gestionar el Service Worker
 * Proporciona estado y m├®todos para controlar el SW
 */
export function useServiceWorker(): UseServiceWorkerReturn {
  const [state, setState] = useState<ServiceWorkerState>({
    isSupported: false,
    isRegistered: false,
    isOnline: typeof navigator !== 'undefined' ? navigator.onLine : true,
    registration: null,
    updateAvailable: false,
  });

  // Registrar Service Worker
  useEffect(() => {
    if (typeof window === 'undefined') return;

    const isSupported = 'serviceWorker' in navigator;
    setState((prev) => ({ ...prev, isSupported }));

    if (!isSupported) return;

    // No registrar en desarrollo (excepto si se fuerza)
    const isDev = process.env.NODE_ENV === 'development';
    const forceSW = process.env.NEXT_PUBLIC_FORCE_SW === 'true';
    
    if (isDev && !forceSW) {
      console.log('[useServiceWorker] SW deshabilitado en desarrollo');
      return;
    }

    const registerSW = async () => {
      try {
        const registration = await navigator.serviceWorker.register('/sw.js', {
          scope: '/',
          updateViaCache: 'none',
        });

        console.log('[useServiceWorker] SW registrado:', registration.scope);

        setState((prev) => ({
          ...prev,
          isRegistered: true,
          registration,
        }));

        // Detectar actualizaciones
        registration.addEventListener('updatefound', () => {
          const newWorker = registration.installing;
          
          if (newWorker) {
            newWorker.addEventListener('statechange', () => {
              if (newWorker.state === 'installed' && navigator.serviceWorker.controller) {
                console.log('[useServiceWorker] Nueva versi├│n disponible');
                setState((prev) => ({ ...prev, updateAvailable: true }));
              }
            });
          }
        });

        // Comprobar actualizaciones peri├│dicamente
        setInterval(() => {
          registration.update();
        }, 60 * 60 * 1000); // Cada hora

      } catch (error) {
        console.error('[useServiceWorker] Error registrando SW:', error);
      }
    };

    // Esperar a que la p├ígina cargue
    if (document.readyState === 'complete') {
      registerSW();
    } else {
      window.addEventListener('load', registerSW);
      return () => window.removeEventListener('load', registerSW);
    }
  }, []);

  // Detectar cambios de conexi├│n
  useEffect(() => {
    if (typeof window === 'undefined') return;

    const handleOnline = () => {
      setState((prev) => ({ ...prev, isOnline: true }));
      console.log('[useServiceWorker] Conexi├│n restaurada');
    };

    const handleOffline = () => {
      setState((prev) => ({ ...prev, isOnline: false }));
      console.log('[useServiceWorker] Sin conexi├│n');
    };

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Actualizar a nueva versi├│n
  const update = useCallback(async () => {
    if (!state.registration?.waiting) return;

    state.registration.waiting.postMessage({ type: 'SKIP_WAITING' });

