    return () => {
      window.removeEventListener(SESSION_EXPIRED_EVENT, handleSessionExpiredEvent as EventListener);
    };
  }, [enabled, isAuthenticated, handleSessionExpired]);

  return {
    updateLastActivity,
    verifySession,
    refreshToken,
    handleSessionExpired,
  };
}

