const processQueue = (error: any = null) => {
  failedQueue.forEach(promise => {
    if (error) {
      promise.reject(error);
    } else {
      promise.resolve();
    }
  });
  
  failedQueue = [];
};

/**
 * ­ƒöÉ SECURITY: Obtener CSRF token del servidor
 * Llamar despu├®s del login para obtener el token
 */
export const fetchCSRFToken = async (): Promise<string | null> => {
  try {
    const response = await apiClient.get('/api/security/csrf-token');
    csrfToken = response.data.token;
    return csrfToken;
  } catch (error) {
    console.warn('No se pudo obtener CSRF token:', error);
    return null;
  }
};

// Interceptor de REQUEST: Agregar CSRF token
apiClient.interceptors.request.use(
  (config: InternalAxiosRequestConfig) => {
    // ­ƒöÉ SECURITY: Agregar CSRF token a requests mutantes
    const mutatingMethods = ['POST', 'PUT', 'PATCH', 'DELETE'];
    if (config.method && mutatingMethods.includes(config.method.toUpperCase())) {
      if (csrfToken && config.headers) {
        config.headers['X-CSRF-Token'] = csrfToken;
      }
    }
    
    // ­ƒöÉ SECURITY: Los tokens se env├¡an autom├íticamente via cookies HttpOnly
    // No se necesita Authorization header - withCredentials: true maneja todo
    
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Interceptor de RESPONSE: Renovar token si expira
apiClient.interceptors.response.use(
  (response) => {
    // ­ƒöÉ SECURITY: Los tokens ahora se manejan via cookies HttpOnly
    // No guardamos tokens en localStorage (previene XSS)
    return response;
  },
  async (error: AxiosError) => {
    const originalRequest = error.config as InternalAxiosRequestConfig & { _retry?: boolean };
    
    // Si el error es 401 (no autorizado) y no hemos intentado renovar a├║n
    if (error.response?.status === 401 && !originalRequest._retry) {
      
      // Si ya estamos renovando, agregar a la cola
      if (isRefreshing) {
        return new Promise((resolve, reject) => {
          failedQueue.push({ resolve, reject });
        })
          .then(() => {
            return apiClient(originalRequest);
          })
          .catch((err) => {
            return Promise.reject(err);
          });
      }

      originalRequest._retry = true;
      isRefreshing = true;

      try {
        // ­ƒöÉ SECURITY: Intentar renovar el token via cookies HttpOnly
        // El refresh token est├í en una cookie HttpOnly, el servidor lo leer├í autom├íticamente
        const response = await axios.post(
          `${API_URL}/api/auth/refresh`, 
          {}, // Body vac├¡o - el refresh token va en la cookie
          { withCredentials: true } // Para cookies HttpOnly
        );

        // Verificar que la respuesta fue exitosa
        if (!response.data.success) {
          throw new Error('Error al renovar token');
        }

        // ­ƒöÉ SECURITY: Los nuevos tokens se establecen autom├íticamente en cookies HttpOnly
        // No necesitamos guardarlos en localStorage

        // Procesar cola de requests fallidos
        processQueue();
        isRefreshing = false;

        // Reintentar el request original
        return apiClient(originalRequest);

      } catch (refreshError) {
        // Fallo al renovar token, cerrar sesi├│n
        processQueue(refreshError);
        isRefreshing = false;
        
        // ­ƒöÉ SECURITY: Solo limpiar localStorage de tokens legacy y redirigir
        if (typeof window !== 'undefined') {
          // Limpiar tokens legacy que puedan quedar de versiones anteriores
          localStorage.removeItem('access_token');
          localStorage.removeItem('refresh_token');
          const locale = window.location.pathname.split('/')[1];
          const prefix = /^[a-z]{2}$/.test(locale) ? locale : 'es';
          window.location.href = `/${prefix}/area-clientes`;
        }
        
        return Promise.reject(refreshError);
      }
    }

    return Promise.reject(error);
  }
);

export default apiClient;

/**
 * ­ƒöÉ SECURITY: Limpiar tokens y cerrar sesi├│n
 */
export const clearAuthTokens = () => {
  csrfToken = null;
  // ­ƒöÉ SECURITY: Limpiar tokens legacy de localStorage (por si migraci├│n incompleta)
  if (typeof window !== 'undefined') {
    localStorage.removeItem('access_token');
    localStorage.removeItem('refresh_token');
  }
};

/**
 * Helper para manejar errores de API de forma consistente
 */
export const handleApiError = (error: any): string => {
  console.error('API Error:', error);

  if (error.code === 'ECONNABORTED' || error.message?.includes('timeout')) {
    return 'La solicitud tard├│ demasiado tiempo. Por favor, intenta nuevamente.';
  }

  if (error.response) {
    const status = error.response.status;
    const data = error.response.data;

    if (data?.message) {
      return data.message;
    }

    switch (status) {
      case 400:
        return 'Los datos enviados no son v├ílidos.';
      case 401:
        return 'Tu sesi├│n ha expirado. Redirigiendo al login...';
      case 403:
        return 'No tienes permisos para realizar esta acci├│n.';
      case 404:
        return 'El recurso solicitado no fue encontrado.';
      case 429:
        return 'Demasiadas solicitudes. Por favor, espera un momento.';
      case 500:
        return 'Error interno del servidor. Nuestro equipo ha sido notificado.';
      case 503:
        return 'El servicio no est├í disponible temporalmente. Intenta en unos minutos.';
      case 504:
        return 'La solicitud tard├│ demasiado tiempo. Por favor, intenta nuevamente.';
      default:
        return 'Ocurri├│ un error inesperado. Por favor, intenta nuevamente.';
    }
  }

  if (error.request) {
    return 'No se pudo conectar con el servidor. Verifica tu conexi├│n a internet.';
  }

  return 'Error inesperado. Por favor, intenta nuevamente.';
};

const fs = require('fs');
const path = require('path');

// Configuration
const TEXTS_DIR = path.join(__dirname, '../messages');
const SOURCE_LANG = 'es'; // Spanish is the source of truth
const TARGET_LANGS = ['en', 'de', 'it', 'zh'];

// Helper to read JSON
const readJson = (lang) => {
    const filePath = path.join(TEXTS_DIR, `${lang}.json`);
    if (!fs.existsSync(filePath)) return {};
    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
};

// Helper to write JSON
const writeJson = (lang, data) => {
    const filePath = path.join(TEXTS_DIR, `${lang}.json`);
    fs.writeFileSync(filePath, JSON.stringify(data, null, 4), 'utf8');
    console.log(`Ô£à Updated ${lang}.json`);
};

// Recursive function to ensure keys exist
const syncKeys = (source, target, langCode) => {
    const result = { ...target }; // copy target to maintain existing translations

    for (const key in source) {
        if (typeof source[key] === 'object' && source[key] !== null) {
            // If it's an object, recurse
            result[key] = syncKeys(source[key], result[key] || {}, langCode);
        } else {
            // If it's a value
            if (result[key] === undefined || result[key] === "") {
                // MISSING KEY: Use a fallback strategy
                // For now, we COPY the Spanish text but mark it (optional) or leave it as Spanish 
                // so it doesn't break the UI with "footer.contact".
                // Ideally, we would translate this.
                // But for now, having Spanish text is better than "footer.contact".
                result[key] = source[key];
                console.log(`[${langCode}] Added missing key: ${key}`);
            }
        }
    }
    return result;
};

// Main execution
const main = () => {
    console.log(`­ƒöä Syncing keys from ${SOURCE_LANG.toUpperCase()} to [${TARGET_LANGS.join(', ')}]...`);

    try {
        const sourceData = readJson(SOURCE_LANG);

        TARGET_LANGS.forEach(lang => {
            const targetData = readJson(lang);
            const syncedData = syncKeys(sourceData, targetData, lang);
            writeJson(lang, syncedData);
        });

        console.log('Ô£¿ All languages synced successfully!');
    } catch (error) {
        console.error('ÔØî Error syncing keys:', error);
    }
};

main();

const fs = require('fs');
const path = require('path');
const { OpenAI } = require('openai');

// Configuration
const EN_PATH = path.join(__dirname, '../messages/en.json');
const TARGET_LANGS = ['es', 'de', 'it', 'zh'];
const OPENAI_API_KEY = process.env.OPENAI_API_KEY;

// Language Names for Prompt
const LANG_NAMES = {
    es: 'Spanish (Spain)',
    de: 'German (Formal)',
    it: 'Italian',
    zh: 'Chinese (Simplified)',
};

const SYSTEM_PROMPT = (langName) => `
You are a professional translator for "Granja Mari Pepa", a premium food distribution company for HORECA (Hotels, Restaurants, Catering).
Target Language: ${langName}

Your tone must be:
- Professional and B2B oriented.
- "Premium" and exclusive.
- Concise but impactful.
- For UI terms (Save, Cancel), use standard conventions.

Translate the provided JSON keys from English to the target language.
Return ONLY valid JSON. Do not include markdown formatting like \`\`\`json.
`;

// Helper to determine if a value is an object
const isObject = (val) => val && typeof val === 'object' && !Array.isArray(val);

async function translateLanguage(openai, en, langCode) {
    const targetPath = path.join(__dirname, `../messages/${langCode}.json`);
    let targetData = {};

    if (fs.existsSync(targetPath)) {
        try {
            targetData = JSON.parse(fs.readFileSync(targetPath, 'utf8'));
        } catch (e) {
            console.log(`ÔÜá´©Å  Could not parse existing ${langCode}.json, starting fresh.`);
        }
    }

    // Find missing keys
    const missing = {};
    let missingCount = 0;

    function findMissing(source, target, collection) {
        for (const key in source) {
            if (isObject(source[key])) {
                if (!target[key]) target[key] = {};

                // Create a sub-collection for this key to maintain structure
                const subCollection = {};
                const hasMissingChildren = findMissing(source[key], target[key], subCollection);

                if (hasMissingChildren) {
                    collection[key] = subCollection;
                }
            } else {
                // It's a string (or close enough)
                if (!target[key] || target[key] === '' || target[key] === source[key]) {
                    // Translate if missing or identical to English (assuming copy-paste placeholder)
                    // Exception: es might be identical to en for "Email", "Zoom", etc. but usually distinct.
                    // For de/it/zh, identical = missing.
                    collection[key] = source[key];
                    missingCount++;
                }
            }
        }
        return Object.keys(collection).length > 0;
    }

    findMissing(en, targetData, missing);

    if (missingCount === 0) {
        console.log(`Ô£à ${langCode}: Up to date.`);
        return;
    }

    console.log(`­ƒîì Translating ${missingCount} keys to ${LANG_NAMES[langCode]}...`);

    // Chunking logic can refer to original TS if needed, we assume < 4000 tokens for now.

    try {
        const completion = await openai.chat.completions.create({
            messages: [
                { role: 'system', content: SYSTEM_PROMPT(LANG_NAMES[langCode]) },
                { role: 'user', content: JSON.stringify(missing) }
            ],
            model: 'gpt-4o',
            response_format: { type: 'json_object' },
            temperature: 0.3,
        });

        const rawContent = completion.choices[0].message.content;
        const translatedChunk = JSON.parse(rawContent);

        // Merge back
        const deepMerge = (target, source) => {
            for (const key in source) {
                if (isObject(source[key]) && key in target) {
                    deepMerge(target[key], source[key]);
                } else {
                    target[key] = source[key];
                }
            }
        };

        deepMerge(targetData, translatedChunk);

        fs.writeFileSync(targetPath, JSON.stringify(targetData, null, 4), 'utf8');
        console.log(`­ƒÆ¥ Saved ${langCode}.json`);

    } catch (error) {
        console.error(`ÔØî Failed to translate ${langCode}:`, error.message);
    }
}

async function main() {
    console.log('­ƒÜÇ Starting AI Translation Service (JS Mode)...');

    if (!OPENAI_API_KEY) {
        console.error('ÔØî Error: OPENAI_API_KEY environment variable is not set.');
        process.exit(1);
    }

    const openai = new OpenAI({ apiKey: OPENAI_API_KEY });
    const en = JSON.parse(fs.readFileSync(EN_PATH, 'utf8'));

    // Sequential execution
    for (const lang of TARGET_LANGS) {
        await translateLanguage(openai, en, lang);
    }

    console.log('Ô£¿ All translations completed!');
}

main();

